INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Acurioustractor/act-global-infrastructure/dev', 'dev', 'Acurioustractor', 'act-global-infrastructure', 'community', 'dev Acurioustractor act-global-infrastructure community dev是ACT生态系统的mono-repo，用于命令中心、脚本和基础设施的管理 devはACTエコシステムのmono-repoで、コマンドセンター、スクリプト、インフラストラクチャを管理する dev는 ACT 생태계의 mono-repo로 명령 센터, 스크립트 및 인프라를 관리한다 El ecosistema ACT es un mono-repo que integra Command Center, scripts y infraestructura para desarrolladores L''écosystème ACT est un mono-repo qui intègre Command Center, scripts et infrastructure pour les développeurs Das ACT-Ökosystem ist ein Mono-Repo, das Command Center, Skripte und Infrastruktur für Entwickler integriert O ACT Ecosystem é um repositório mono que abrange Command Center, scripts e infraestrutura para desenvolvedores ACT Ecosystem — монорепозиторий, включающий Command Center, скрипты и инфраструктуру для разработчиков نظام بيئي ACT هو مخزن وحيد يغطي مركز القيادة والسكريبتات والبنية التحتية للمطورين ACT Ecosystem — mono-repo for Command Center, scripts, and infrastructure 如何使用dev 什么是ACT生态系统 dev安装 dev设置 dev替代 dev vs 其他工具 ACT Ecosystem — mono-repo for Command Center, scripts, and infrastructure');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-device/agent-device', 'community', 'callstackincubator', 'agent-device', 'callstackincubator/agent-device', 'agent-device', 0, 0, 37, '2026-03-04T13:07:01.798Z', '2026-03-04T14:28:53.406Z', 'eeb820f46534eb7b09b0398e89e1ea5e2c01da8178d93f7997f5f688819b8485', '{"id":"callstackincubator/agent-device/agent-device","name":"agent-device","description":{"zh":"agent-device CLI是一款用于控制和管理iOS和Android设备的命令行工具，支持AI代理功能","ja":"AIエージェント用デバイス制御CLIは、iOSとAndroidのデバイスを管理するためのコマンドラインツール","ko":"agent-device CLI는 iOS 및 Android 디바이스를 제어하고 관리하는 명령줄 도구로 AI 에이전트 기능을 지원","es":"La herramienta de línea de comandos ''agent-device'' permite controlar dispositivos iOS y Android para agentes de IA","fr":"L''outil en ligne de commande ''agent-device'' permet de contrôler les appareils iOS et Android pour les agents IA","de":"Das Befehlszeilen-Tool ''agent-device'' ermöglicht die Steuerung von iOS- und Android-Geräten für KI-Agents","pt":"O agent-device é um CLI para controlar dispositivos iOS e Android para Ferramentas de IA, permitindo uma integração perfeita.","ru":"ИИ Агенты: agent-device — это CLI для управления устройствами iOS и Android, обеспечивая идеальную интеграцию.","ar":"آلة الذكاء الاصطناعي: agent-device هو واجهة سطر الأوامر لتحكم الأجهزة iOS و Android، مما يتيح التكامل المثالي.","en":"CLI to control iOS and Android devices for AI agents"},"seo":{"title":{"zh":"AI代理设备控制CLI - iOS和Android设备管理","ja":"AIエージェント用デバイス制御CLI - iOSとAndroidの管理","ko":"AI 에이전트 디바이스 제어 CLI - iOS 및 Android 디바이스 관리","es":"Controla dispositivos iOS y Android para Agentes de IA co...","fr":"Contrôle des appareils iOS et Android pour les agents IA ...","de":"Steuerung von iOS- und Android-Geräten für KI-Agents mit CLI","pt":"Controle de Dispositivos para Ferramentas de IA","ru":"Управление устройствами для ИИ Агентов","ar":"تحكم الأجهزة لآلات الذكاء الاصطناعي","en":"agent-device"},"description":{"zh":"agent-device CLI是一款用于控制和管理iOS和Android设备的命令行工具，支持AI代理功能","ja":"AIエージェント用デバイス制御CLIは、iOSとAndroidのデバイスを管理するためのコマンドラインツール","ko":"agent-device CLI는 iOS 및 Android 디바이스를 제어하고 관리하는 명령줄 도구로 AI 에이전트 기능을 지원","es":"La herramienta de línea de comandos ''agent-device'' permite controlar dispositivos iOS y Android para agentes de IA","fr":"L''outil en ligne de commande ''agent-device'' permet de contrôler les appareils iOS et Android pour les agents IA","de":"Das Befehlszeilen-Tool ''agent-device'' ermöglicht die Steuerung von iOS- und Android-Geräten für KI-Agents","pt":"O agent-device é um CLI para controlar dispositivos iOS e Android para Ferramentas de IA, permitindo uma integração perfeita.","ru":"ИИ Агенты: agent-device — это CLI для управления устройствами iOS и Android, обеспечивая идеальную интеграцию.","ar":"آلة الذكاء الاصطناعي: agent-device هو واجهة سطر الأوامر لتحكم الأجهزة iOS و Android، مما يتيح التكامل المثالي.","en":"CLI to control iOS and Android devices for AI agents"},"definition":{"en":"CLI to control iOS and Android devices for AI agents"},"features":{"zh":["支持iOS和Android设备管理","提供命令行接口","实现AI代理功能","支持多设备控制","提供设备状态监控"],"ja":["iOSとAndroidのデバイス管理をサポート","コマンドラインインターフェースを提供","AIエージェント機能を実現","複数デバイス制御をサポート","デバイス状態モニタリングを提供"],"ko":["iOS 및 Android 디바이스 관리를 지원","명령줄 인터페이스를 제공","AI 에이전트 기능을 구현","다중 디바이스 제어를 지원","디바이스 상태 모니터링을 제공"],"es":["Control de dispositivos iOS y Android","Interfaz de línea de comandos para agentes de IA","Compatibilidad con entornos de desarrollo de IA","Facilidad de uso y configuración","Soporte para múltiples dispositivos"],"fr":["Contrôle des appareils iOS et Android","Interface en ligne de commande pour les agents IA","Compatibilité avec les environnements de développement de l''IA","Facilité d''utilisation et de configuration","Prise en charge de plusieurs appareils"],"de":["Steuerung von iOS- und Android-Geräten","Befehlszeilen-Schnittstelle für KI-Agents","Kompatibilität mit KI-Entwicklungsumgebungen","Einfachheit bei der Verwendung und Konfiguration","Unterstützung für mehrere Geräte"],"pt":["Controle de dispositivos iOS e Android","Integração perfeita com Ferramentas de IA","CLI fácil de usar","Suporte a comandos personalizados","Segurança e estabilidade garantidas"],"ru":["Управление устройствами iOS и Android","Идеальная интеграция с ИИ Агентами","Легко используемый CLI","Поддержка пользовательских команд","Гарантия безопасности и стабильности"],"ar":["تحكم في أجهزة iOS و Android","التكامل المثالي مع آلات الذكاء الاصطناعي","واجهة سطر الأوامر سهلة الاستخدام","دعم أوامر مخصصة","ضمان الأمان والاستقرار"]},"keywords":{"zh":["AI代理设备控制","iOS和Android设备管理","CLI命令行工具","AI工具","如何使用agent-device","agent-device安装","agent-device设置指南"],"ja":["AIエージェント用デバイス制御","iOSとAndroidのデバイス管理","CLIコマンドラインツール","AIエージェント","AIエージェントの使い方","agent-deviceのインストール","agent-deviceの設定ガイド"],"ko":["AI 에이전트 디바이스 제어","iOS 및 Android 디바이스 관리","CLI 명령줄 도구","AI 에이전트","AI 에이전트의 사용법","agent-device 설치","agent-device 설정 가이드"],"es":["cómo usar agent-device","qué es un agente de IA","alternativas a agent-device","agent-device vs otros herramientas","instalación de agent-device","guía de configuración de agent-device","desarrollo de IA con agent-device"],"fr":["comment utiliser agent-device","qu''est-ce qu''un agent IA","alternatives à agent-device","agent-device vs autres outils","installation d''agent-device","guide de configuration d''agent-device","développement de l''IA avec agent-device"],"de":["wie man agent-device verwendet","was ist ein KI-Agents","alternativen zu agent-device","agent-device vs andere tools","installation von agent-device","konfigurationsanleitung für agent-device","entwicklung von KI mit agent-device"],"pt":["como usar agent-device","o que é agent-device","ferramentas de ia","alternativa ao agent-device","agent-device vs outras ferramentas","instalar agent-device","guia de configuração do agent-device"],"ru":["как использовать agent-device","что такое agent-device","ии агенты","альтернатива agent-device","agent-device vs другие инструменты","установить agent-device","руководство по настройке agent-device"],"ar":["كيفية استخدام agent-device","ما هو agent-device","آلات الذكاء الاصطناعي","بديل لبرنامج agent-device","agent-device مقابل أدوات أخرى","تثبيت agent-device","دليل إعداد برنامج agent-device"]}},"owner":"callstackincubator","repo":"agent-device","repoPath":"callstackincubator/agent-device","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.798Z","topics":[],"category":"community","skillMd":{"name":"agent-device","description":"Automates interactions for iOS simulators/devices and Android emulators/devices. Use when navigating apps, taking snapshots/screenshots, tapping, typing, scrolling, or extracting UI info on mobile targets.","bodyPreview":"# Mobile Automation with agent-device\n\nFor exploration, use snapshot refs. For deterministic replay, use selectors.\nFor structured exploratory QA bug hunts and reporting, use [../dogfood/SKILL.md](../dogfood/SKILL.md).\n\n## Start Here (Read This First)\n\nUse this skill as a router, not a full manual.\n\n1. Pick one mode:\n   - Normal interaction flow\n   - Debug/crash flow\n   - Replay maintenance flow\n2. Run one canonical flow below.\n3. Open references only if blocked.\n\n## Decision Map\n\n- No target co","body":"# Mobile Automation with agent-device\n\nFor exploration, use snapshot refs. For deterministic replay, use selectors.\nFor structured exploratory QA bug hunts and reporting, use [../dogfood/SKILL.md](../dogfood/SKILL.md).\n\n## Start Here (Read This First)\n\nUse this skill as a router, not a full manual.\n\n1. Pick one mode:\n   - Normal interaction flow\n   - Debug/crash flow\n   - Replay maintenance flow\n2. Run one canonical flow below.\n3. Open references only if blocked.\n\n## Decision Map\n\n- No target context yet: `devices` -> pick target -> `open`.\n- Normal UI task: `open` -> `snapshot -i` -> `press/fill` -> `diff snapshot -i` -> `close`\n- Debug/crash: `open <app>` -> `logs clear --restart` -> reproduce -> `network dump` -> `logs path` -> targeted `grep`\n- Replay drift: `replay -u <path>` -> verify updated selectors\n- Remote multi-tenant run: allocate lease -> run commands with tenant isolation flags -> heartbeat/release lease\n- Device-scope isolation run: set iOS simulator set / Android allowlist -> run selectors within scope only\n\n## Canonical Flows\n\n### 1) Normal Interaction Flow\n\n```bash\nagent-device open Settings --platform ios\nagent-device snapshot -i\nagent-device press @e3\nagent-device diff snapshot -i\nagent-device fill @e5 \"test\"\nagent-device close\n```\n\n### 2) Debug/Crash Flow\n\n```bash\nagent-device open MyApp --platform ios\nagent-device logs clear --restart\nagent-device network dump 25\nagent-device logs path\n```\n\nLogging is off by default. Enable only for debugging windows.\n`logs clear --restart` requires an active app session (`open <app>` first).\n\n### 3) Replay Maintenance Flow\n\n```bash\nagent-device replay -u ./session.ad\n```\n\n### 4) Remote Tenant Lease Flow (HTTP JSON-RPC)\n\n```bash\n# Allocate lease\ncurl -sS http://127.0.0.1:${AGENT_DEVICE_DAEMON_HTTP_PORT}/rpc \\\n  -H \"content-type: application/json\" \\\n  -H \"Authorization: Bearer <token>\" \\\n  -d ''{\"jsonrpc\":\"2.0\",\"id\":\"alloc-1\",\"method\":\"agent_device.lease.allocate\",\"params\":{\"runId\":\"run-123\",\"tenantId\":\"acme\",\"ttlMs\":60000}}''\n\n# Use lease in tenant-isolated command execution\nagent-device --daemon-transport http \\\n  --tenant acme \\\n  --session-isolation tenant \\\n  --run-id run-123 \\\n  --lease-id <lease-id> \\\n  session list --json\n\n# Heartbeat and release\ncurl -sS http://127.0.0.1:${AGENT_DEVICE_DAEMON_HTTP_PORT}/rpc \\\n  -H \"content-type: application/json\" \\\n  -H \"Authorization: Bearer <token>\" \\\n  -d ''{\"jsonrpc\":\"2.0\",\"id\":\"hb-1\",\"method\":\"agent_device.lease.heartbeat\",\"params\":{\"leaseId\":\"<lease-id>\",\"ttlMs\":60000}}''\ncurl -sS http://127.0.0.1:${AGENT_DEVICE_DAEMON_HTTP_PORT}/rpc \\\n  -H \"content-type: application/json\" \\\n  -H \"Authorization: Bearer <token>\" \\\n  -d ''{\"jsonrpc\":\"2.0\",\"id\":\"rel-1\",\"method\":\"agent_device.lease.release\",\"params\":{\"leaseId\":\"<lease-id>\"}}''\n```\n\n## Command Skeleton (Minimal)\n\n### Session and navigation\n\n```bash\nagent-device devices\nagent-device devices --platform ios --ios-simulator-device-set /tmp/tenant-a/simulators\nagent-device devices --platform android --android-device-allowlist emulator-5554,device-1234\nagent-device ensure-simulator --device \"iPhone 16\" --ios-simulator-device-set /tmp/tenant-a/simulators\nagent-device ensure-simulator --device \"iPhone 16\" --runtime com.apple.CoreSimulator.SimRuntime.iOS-18-4 --ios-simulator-device-set /tmp/tenant-a/simulators --boot\nagent-device open [app|url] [url]\nagent-device open [app] --relaunch\nagent-device close [app]\nagent-device install <app> <path-to-binary>\nagent-device reinstall <app> <path-to-binary>\nagent-device session list\n```\n\nUse `boot` only as fallback when `open` cannot find/connect to a ready target.\nFor Android emulators by AVD name, use `boot --platform android --device <avd-name>`.\nFor Android emulators without GUI, add `--headless`.\nUse `--target mobile|tv` with `--platform` (required) to pick phone/tablet vs TV targets (AndroidTV/tvOS).\n\nIsolation scoping quick reference:\n- `--ios-simulator-device-set <path>` scopes iOS simulator discovery + command execution to one simulator set.\n- `--android-device-allowlist <serials>` scopes Android discovery/selection to comma/space separated serials.\n- Scope is applied before selectors (`--device`, `--udid`, `--serial`); out-of-scope selectors fail with `DEVICE_NOT_FOUND`.\n- With iOS simulator-set scope enabled, iOS physical devices are not enumerated.\n\nSimulator provisioning quick reference:\n- Use `ensure-simulator` to create or reuse a named iOS simulator inside a device set before starting a session.\n- `--device <name>` is required (e.g. `\"iPhone 16 Pro\"`). `--runtime <id>` pins the runtime; omit to use the newest compatible one.\n- `--boot` boots it immediately. Returns `udid`, `device`, `runtime`, `ios_simulator_device_set`, `created`, `booted`.\n- Idempotent: safe to call repeatedly; reuses an existing matching simulator by default.\n\nTV quick reference:\n- AndroidTV: `open`/`apps` use TV launcher discovery automatically.\n- TV target selection works on emulators/simulators and connected physical devices (AndroidTV + AppleTV).\n- tvOS: runner-driven interactions and snapshots are supported (`snapshot`, `wait`, `press`, `fill`, `get`, `scroll`, `back`, `home`, `app-switcher`, `record` and related selector flows).\n- tvOS `back`/`home`/`app-switcher` map to Siri Remote actions (`menu`, `home`, double-home) in the runner.\n- tvOS follows iOS simulator-only command semantics for helpers like `pinch`, `settings`, and `push`.\n\n### Snapshot and targeting\n\n```bash\nagent-device snapshot -i\nagent-device diff snapshot -i\nagent-device find \"Sign In\" click\nagent-device press @e1\nagent-device fill @e2 \"text\"\nagent-device is visible ''id=\"anchor\"''\n```\n\n`press` is canonical tap command; `click` is an alias.\n\n### Utilities\n\n```bash\nagent-device appstate\nagent-device clipboard read\nagent-device clipboard write \"token\"\nagent-device keyboard status\nagent-device keyboard dismiss\nagent-device perf --json\nagent-device network dump [limit] [summary|headers|body|all]\nagent-device push <bundle|package> <payload.json|inline-json>\nagent-device trigger-app-event screenshot_taken ''{\"source\":\"qa\"}''\nagent-device get text @e1\nagent-device screenshot out.png\nagent-device settings permission grant notifications\nagent-device settings permission reset camera\nagent-device trace start\nagent-device trace stop ./trace.log\n```\n\n### Batch (when sequence is already known)\n\n```bash\nagent-device batch --steps-file /tmp/batch-steps.json --json\n```\n\n### Performance Check\n\n- Use `agent-device perf --json` (or `metrics --json`) after `open`.\n- For detailed metric semantics, caveats, and interpretation guidance, see [references/perf-metrics.md](references/perf-metrics.md).\n\n## Guardrails (High Value Only)\n\n- Re-snapshot after UI mutations (navigation/modal/list changes).\n- Prefer `snapshot -i`; scope/depth only when needed.\n- Use refs for discovery, selectors for replay/assertions.\n- `find \"<query>\" click --json` returns `{ ref, locator, query, x, y }` — all derived from the matched snapshot node. Do not rely on these fields from raw `press`/`click` responses for observability; use `find` instead.\n- Use `fill` for clear-then-type semantics; use `type` for focused append typing.\n- Use `install` for in-place app upgrades (keep app data when platform permits), and `reinstall` for deterministic fresh-state runs.\n- App binary format support for `install`/`reinstall`: Android `.apk`/`.aab`, iOS `.app`/`.ipa`.\n- Android `.aab` requires `bundletool` in `PATH`, or `AGENT_DEVICE_BUNDLETOOL_JAR=<path-to-bundletool-all.jar>` with `java` in `PATH`.\n- Android `.aab` optional: set `AGENT_DEVICE_ANDROID_BUNDLETOOL_MODE=<mode>` to control bundletool `build-apks --mode` (default: `universal`).\n- iOS `.ipa`: extract/install from `Payload/*.app`; when multiple app bundles are present, `<app>` is used as a bundle id/name hint.\n- iOS `appstate` is session-scoped; Android `appstate` is live foreground state. iOS responses include `device_udid` and `ios_simulator_device_set` for isolation verification.\n- iOS `open` responses include `device_udid` and `ios_simulator_device_set` to confirm which simulator handled the session.\n- Clipboard helpers: `clipboard read` / `clipboard write <text>` are supported on Android and iOS simulators; iOS physical devices are not supported yet.\n- Android keyboard helpers: `keyboard status|get|dismiss` report keyboard visibility/type and dismiss via keyevent when visible.\n- `network dump` is best-effort and parses HTTP(s) entries from the session app log file.\n- Biometric settings: iOS simulator supports `settings faceid|touchid <match|nonmatch|enroll|unenroll>`; Android supports `settings fingerprint <match|nonmatch>` where runtime tooling is available.\n- For AndroidTV/tvOS selection, always pair `--target` with `--platform` (`ios`, `android`, or `apple` alias); target-only selection is invalid.\n- `push` simulates notification delivery:\n  - iOS simulator uses APNs-style payload JSON.\n  - Android uses broadcast action + typed extras (string/boolean/number).\n- `trigger-app-event` requires app-defined deep-link hooks and URL template configuration (`AGENT_DEVICE_APP_EVENT_URL_TEMPLATE` or platform-specific variants).\n- `trigger-app-event` requires an active session or explicit selectors (`--platform`, `--device`, `--udid`, `--serial`); on iOS physical devices, custom-scheme triggers require active app context.\n- Canonical trigger behavior and caveats are documented in [`website/docs/docs/commands.md`](../../website/docs/docs/commands.md) under **App event triggers**.\n- Permission settings are app-scoped and require an active session app:\n  `settings permission <grant|deny|reset> <camera|microphone|photos|contacts|notifications> [full|limited]`\n- iOS simulator permission alerts: use `alert wait` then `alert accept/dismiss` — `accept`/`dismiss` retry internally for up to 2 s so you do not need manual sleeps. See [references/permissions.md](references/permissions.md).\n- `full|limited` mode applies only to iOS `photos`; other targets reject mode.\n- On Android, non-ASCII `fill/type` may require an ADB keyboard IME on some system images; only install IME APKs from trusted sources and verify checksum/signature.\n- If using `--save-script`, prefer explicit path syntax (`--save-script=flow.ad` or `./flow.ad`).\n- For tenant-isolated remote runs, always pass `--tenant`, `--session-isolation tenant`, `--run-id`, and `--lease-id` together.\n- Use short lease TTLs and heartbeat only while work is active; release leases immediately after run completion/failure.\n- Env equivalents for scoped runs: `AGENT_DEVICE_IOS_SIMULATOR_DEVICE_SET` (compat `IOS_SIMULATOR_DEVICE_SET`) and\n  `AGENT_DEVICE_ANDROID_DEVICE_ALLOWLIST` (compat `ANDROID_DEVICE_ALLOWLIST`).\n\n## Security and Trust Notes\n\n- Prefer a preinstalled `agent-device` binary over on-demand package execution.\n- If install is required, pin an exact version (for example: `npx --yes agent-device@<exact-version> --help`).\n- Signing/provisioning environment variables are optional, sensitive, and only for iOS physical-device setup.\n- Logs/artifacts are written under `~/.agent-device`; replay scripts write to explicit paths you provide.\n- For remote daemon mode, prefer `AGENT_DEVICE_DAEMON_SERVER_MODE=http|dual` with `AGENT_DEVICE_HTTP_AUTH_HOOK` and tenant-scoped lease admission.\n- Keep logging off unless debugging and use least-privilege/isolated environments for autonomous runs.\n\n## Common Mistakes\n\n- Mixing debug flow into normal runs (keep logs off unless debugging).\n- Continuing to use stale refs after screen transitions.\n- Using URL opens with Android `--activity` (unsupported combination).\n- Treating `boot` as default first step instead of fallback.\n\n## References\n\n- [references/snapshot-refs.md](references/snapshot-refs.md)\n- [references/logs-and-debug.md](references/logs-and-debug.md)\n- [references/session-management.md](references/session-management.md)\n- [references/permissions.md](references/permissions.md)\n- [references/video-recording.md](references/video-recording.md)\n- [references/coordinate-system.md](references/coordinate-system.md)\n- [references/batching.md](references/batching.md)\n- [references/perf-metrics.md](references/perf-metrics.md)\n- [references/remote-tenancy.md](references/remote-tenancy.md)\n"},"lastSynced":"2026-03-04T14:28:53.406Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Automation Agents needing CLI control over iOS and Android devices.","zh":"适用于需要通过CLI控制iOS和Android设备的移动自动化代理。","ja":"iOSとAndroidデバイスのCLIコントロールが必要なモバイル自動化エージェントに適しています。","ko":"CLI를 통해 iOS 및 Android 디바이스를 제어해야 하는 모바일 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización móvil que necesitan control de CLI sobre dispositivos iOS y Android.","fr":"Idéal pour les agents d''automatisation mobile nécessitant un contrôle CLI sur les appareils iOS et Android.","de":"Perfekt für Mobile Automation Agents, die CLI-Kontrolle über iOS- und Android-Geräte benötigen.","pt":"Perfeito para agentes de automação móvel que necessitam de controle CLI sobre dispositivos iOS e Android.","ru":"Идеально для агентов мобильной автоматизации, которым требуется управление CLI над устройствами iOS и Android.","ar":"مثالي لعمليات إتمتة الهاتف المحمول التي تحتاج إلى التحكم في واجهة سطر الأوامر على أجهزة iOS و Android."},"recommendation":{"en":"Empowers agents to automate mobile interactions using snapshot refs for exploration and selectors for deterministic replay, leveraging CLI protocols for seamless device control.","zh":"赋予代理使用快照引用进行探索和选择器进行确定性回放的能力，利用CLI协议实现无缝的设备控制，自动化移动交互。","ja":"エージェントにスナップショット参照を使用して探索し、セレクターを使用して決定的な再生を実行し、CLIプロトコルを利用してシームレスなデバイス制御を実現することで、モバイルの相互作用を自動化する能力を付与します。","ko":"스냅샷 참조를 사용하여 탐색하고 선택기를 사용하여 결정적인 재생을 실행하며 CLI 프로토콜을 활용하여 무결점 디바이스 제어를 구현함으로써 모바일 상호 작용을 자동화할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a automatizar las interacciones móviles utilizando referencias de instantáneas para la exploración y selectores para una reproducción determinista, aprovechando los protocolos CLI para un control de dispositivo sin problemas.","fr":"Permet aux agents d''automatiser les interactions mobiles en utilisant des références d''instantanés pour l''exploration et des sélecteurs pour une lecture déterministe, en exploitant les protocoles CLI pour un contrôle d''appareil sans interruption.","de":"Ermöglicht es den Agents, mobile Interaktionen zu automatisieren, indem sie Snapshot-Referenzen für die Exploration und Selektoren für eine deterministische Wiedergabe verwenden, und nutzt CLI-Protokolle für eine nahtlose Gerätesteuerung.","pt":"Habilita os agentes a automatizar interações móveis usando referências de instantâneos para exploração e seletor para reprodução determinística, aproveitando protocolos CLI para controle de dispositivo sem interrupção.","ru":"Наделяет агентов возможностью автоматизировать мобильные взаимодействия, используя ссылки на снимки для исследования и селекторы для детерминированной воспроизведения, используя протоколы CLI для бесшовного управления устройством.","ar":"يمكن للعميل تشغيل التفاعلات المتنقلة باستخدام مراجع لقطات للتحقيق واختيار معايير لإعادة تشغيل حتمية، واستخدام بروتوكولات واجهة سطر الأوامر للتحكم في الجهاز دون انقطاع."},"useCases":{"en":["Automating mobile app testing","Debugging crash flows on iOS and Android","Replaying maintenance flows for QA bug hunts"],"zh":["自动化移动应用测试","在iOS和Android上调试崩溃流程","为QA漏洞狩猎重放维护流程"],"ja":["モバイルアプリのテストを自動化する","iOSとAndroidでクラッシュフローをデバッグする","QAのバグハントのためにメンテナンスフローを再生する"],"ko":["모바일 애플리케이션 테스트 자동화","iOS 및 Android에서 충돌 흐름 디버깅","QA 버그 사냥을 위한 유지 보수 흐름 재생"],"es":["Automatización de pruebas de aplicaciones móviles","Depuración de flujos de bloqueo en iOS y Android","Reproducción de flujos de mantenimiento para cacerías de errores de QA"],"fr":["Automatisation des tests d''applications mobiles","Débogage des flux de blocage sur iOS et Android","Relecture des flux de maintenance pour les chasses aux bogues QA"],"de":["Automatisierung von Tests für mobile Apps","Fehlerbehebung bei Absturzflüssen auf iOS und Android","Wiedergabe von Wartungsflüssen für QA-Fehlerjagd"],"pt":["Automatizar testes de aplicativos móveis","Depurar fluxos de crash em iOS e Android","Repetir fluxos de manutenção para caçadas de bugs de QA"],"ru":["Автоматизация тестирования мобильных приложений","Отладка потоков краха на iOS и Android","Повторение потоков обслуживания для охоты за ошибками QA"],"ar":["تأتمتة اختبار تطبيقات الهاتف المحمول","تصحيح تدفقات انهيار على نظامي التشغيل iOS و Android","إعادة تشغيل تدفقات الصيانة للصيد المحكم للخطأ في جودة ضمان"]},"limitations":{"en":["Requires CLI access","Limited to iOS and Android devices","Needs snapshot refs or selectors for operation"],"zh":["需要CLI访问","仅限iOS和Android设备","需要快照引用或选择器进行操作"],"ja":["CLIアクセスが必要","iOSとAndroidデバイスのみ","操作にはスナップショット参照またはセレクターが必要"],"ko":["CLI 액세스가 필요합니다.","iOS 및 Android 디바이스만 해당","동작을 수행하려면 스냅샷 참조 또는 선택기가 필요합니다."],"es":["Requiere acceso CLI","Limitado a dispositivos iOS y Android","Necesita referencias de instantáneas o selectores para operar"],"fr":["Nécessite un accès CLI","Limité aux appareils iOS et Android","Nécessite des références d''instantanés ou des sélecteurs pour fonctionner"],"de":["Benötigt CLI-Zugriff","Begrenzt auf iOS- und Android-Geräte","Benötigt Snapshot-Referenzen oder Selektoren für den Betrieb"],"pt":["Exige acesso CLI","Limitado a dispositivos iOS e Android","Necessita de referências de instantâneos ou seletor para operação"],"ru":["Требует доступа CLI","Ограничен устройствами iOS и Android","Требует ссылок на снимки или селектора для работы"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","محدود بأجهزة iOS و Android","يتطلب مراجع لقطات أو محدد لتشغيل"]},"version":3},"contentHash":"eeb820f46534eb7b09b0398e89e1ea5e2c01da8178d93f7997f5f688819b8485","qualityScore":37}');
