INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zotoio/x-fidelity/xfi-create-plan', 'xfi-create-plan', 'zotoio', 'x-fidelity', 'community', 'xfi-create-plan zotoio x-fidelity community xfi-create-plan是一个用于检查代码是否符合框架规定的CLI工具，帮助开发者确保代码质量和一致性 xfi-create-planは、フレームワークのルールに従っているかをチェックするCLIツールです。開発者がコードの品質と一致性を確保するのに役立ちます xfi-create-plan은 프레임워크 규칙을 확인하는 CLI 도구입니다. 개발자가 코드 품질과 일관성을 보장하는 데 도움이 됩니다 xfi-create-plan es una herramienta de línea de comandos para verificar la adherencia a frameworks opinionados xfi-create-plan est un outil de ligne de commande pour vérifier la conformité aux frameworks opinionés xfi-create-plan ist ein Tool für die Kommandozeile, um die Konformität mit opinionierten Frameworks zu überprüfen O xfi-create-plan é uma ferramenta de linha de comando para verificar a adesão ao framework opinonated, garantindo a consistência e a qualidade do código ИИ Агент xfi-create-plan - это инструмент командной строки для проверки соблюдения opinonated фреймворка, обеспечивающий согласованность и качество кода أداة xfi-create-plan هي أداة سطر أوامر للتحقق من اتباع الإطار المتحمس، مما يضمن الاتساق وجودة الكود cli for opinionated framework adherence checks xfi-create-plan AI智能工具 CLI工具 框架检查 代码质量 一致性检查 如何使用xfi-create-plan xfi-create-plan安装 xfi-create-plan设置指南 cli for opinionated framework adherence checks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zzfancitizen/agent-skills-self-learning-sample/create-agent', 'community', 'zzfancitizen', 'agent-skills-self-learning-sample', 'zzfancitizen/agent-skills-self-learning-sample', 'create-agent', 0, 0, 37, '2026-03-04T13:07:01.835Z', '2026-03-04T14:45:18.307Z', '4acde0af0b1643da55b0fc2e9202c851ed36c31a470fb11854768081f8596372', '{"id":"zzfancitizen/agent-skills-self-learning-sample/create-agent","name":"create-agent","description":{"zh":"Create-Agent技能允许开发者创建和管理AI智能代理，实现自学习和自动化，提高开发效率","ja":"Create-Agentスキルは、開発者がAIエージェントを作成および管理し、セルフラーニングと自動化を実現できるようにします","ko":"Create-Agent 스킬을 사용하면 개발자가 AI 에이전트를 생성하고 관리하여 셀프 러닝과 자동화를 구현할 수 있습니다","es":"create-agent es una habilidad de agente de IA que permite el aprendizaje automático. Aprende a crear agentes con nuestro ejemplo","fr":"create-agent est une compétence d''agent d''IA qui permet l''apprentissage automatique. Découvrez comment créer des agents avec notre exemple","de":"create-agent ist eine Fähigkeit von KI-Agents, die maschinelles Lernen ermöglicht. Erfahren Sie, wie Sie Agenten mit unserem Beispiel erstellen","pt":"O create-agent é uma ferramenta de código aberto para criar agentes de IA personalizados. Aprenda a usar React, Python e Node.js para construir soluções de automação","ru":"Create-agent - это открытый инструмент для создания индивидуальных ИИ Агентов. Узнайте, как использовать React, Python и Node.js для построения решений автоматизации","ar":"إن create-agent هو أداة مفتوحة المصدر لإنشاء وكلاء الذكاء الاصطناعي المخصصين. تعلم كيفية استخدام React و Python و Node.js لبناء حلول الأتمتة","en":"agent-skills-self-learning-sample"},"seo":{"title":{"zh":"AI智能代理创建 - Create-Agent","ja":"AIエージェントを作成 - Create-Agent","ko":"AI 에이전트 생성 - Create-Agent","es":"Crea Agentes de IA con create-agent","fr":"Créez des Agents d''IA avec create-agent","de":"Erstellen Sie KI-Agents mit create-agent","pt":"Crie Agentes de IA com create-agent","ru":"ИИ Агенты: Создайте с помощью create-agent","ar":"وكلاء الذكاء الاصطناعي: أنشئ مع create-agent","en":"create-agent"},"description":{"zh":"Create-Agent技能允许开发者创建和管理AI智能代理，实现自学习和自动化，提高开发效率","ja":"Create-Agentスキルは、開発者がAIエージェントを作成および管理し、セルフラーニングと自動化を実現できるようにします","ko":"Create-Agent 스킬을 사용하면 개발자가 AI 에이전트를 생성하고 관리하여 셀프 러닝과 자동화를 구현할 수 있습니다","es":"create-agent es una habilidad de agente de IA que permite el aprendizaje automático. Aprende a crear agentes con nuestro ejemplo","fr":"create-agent est une compétence d''agent d''IA qui permet l''apprentissage automatique. Découvrez comment créer des agents avec notre exemple","de":"create-agent ist eine Fähigkeit von KI-Agents, die maschinelles Lernen ermöglicht. Erfahren Sie, wie Sie Agenten mit unserem Beispiel erstellen","pt":"O create-agent é uma ferramenta de código aberto para criar agentes de IA personalizados. Aprenda a usar React, Python e Node.js para construir soluções de a...","ru":"Create-agent - это открытый инструмент для создания индивидуальных ИИ Агентов. Узнайте, как использовать React, Python и Node.js для построения решений автом...","ar":"إن create-agent هو أداة مفتوحة المصدر لإنشاء وكلاء الذكاء الاصطناعي المخصصين. تعلم كيفية استخدام React و Python و Node.js لبناء حلول الأتمتة","en":"agent-skills-self-learning-sample"},"definition":{"en":"agent-skills-self-learning-sample"},"features":{"zh":["创建和管理AI智能代理","实现自学习和自动化","支持React、Python、Node.js等开发框架","提供CLI命令行工具","支持Agent扩展和自定义"],"ja":["AIエージェントを作成および管理","セルフラーニングと自動化を実現","React、Python、Node.jsなどの開発フレームワークをサポート","CLIコマンドラインツールを提供","エージェントの拡張とカスタマイズをサポート"],"ko":["AI 에이전트 생성 및 관리","셀프 러닝과 자동화를 구현","React, Python, Node.js 등의 개발 프레임워크 지원","CLI 명령행 도구 제공","에이전트 확장 및 커스터마이징 지원"],"es":["Aprendizaje automático","Creación de agentes de IA personalizados","Integración con React, Python y Node.js","Uso de la interfaz de línea de comandos (CLI)","Compatibilidad con diferentes plataformas"],"fr":["Apprentissage automatique","Création d''agents d''IA personnalisés","Intégration avec React, Python et Node.js","Utilisation de l''interface de ligne de commande (CLI)","Compatibilité avec différentes plateformes"],"de":["Maschinelles Lernen","Erstellung von benutzerdefinierten KI-Agents","Integration mit React, Python und Node.js","Verwendung der Kommandozeilen-Schnittstelle (CLI)","Kompatibilität mit verschiedenen Plattformen"],"pt":["Crie agentes de IA personalizados com React e Python","Integre com Node.js para construir soluções de automação","Use a CLI para gerenciar e deployar agentes de IA","Aprenda com exemplos de código e documentação completa","Melhore a eficiência e a automação com agentes de IA"],"ru":["Создайте индивидуальных ИИ Агентов с помощью React и Python","Интегрируйте с Node.js для построения решений автоматизации","Используйте CLI для управления и деплоя ИИ Агентов","Узнайте с помощью примеров кода и полной документации","Улучшите эффективность и автоматизацию с ИИ Агентами"],"ar":["أنشئ وكلاء الذكاء الاصطناعي المخصصين مع React و Python","دمج مع Node.js لبناء حلول الأتمتة","استخدم CLI لإدارة وتنفيذ وكلاء الذكاء الاصطناعي","تعلم مع أمثلة من الكود والتوثيق الكامل","تحسين الكفاءة والأتمتة مع وكلاء الذكاء الاصطناعي"]},"keywords":{"zh":["AI智能代理","Create-Agent","自学习","自动化","React","Python","Node.js","CLI","Agent","如何使用Create-Agent"],"ja":["AIエージェント","Create-Agent","セルフラーニング","自動化","React","Python","Node.js","CLI","エージェント","Create-Agentの使い方"],"ko":["AI 에이전트","Create-Agent","셀프 러닝","자동화","React","Python","Node.js","CLI","에이전트","Create-Agent 사용법"],"es":["cómo crear agentes de IA","qué es un agente de IA","create-agent vs otros agentes de IA","instalación de create-agent","guía de configuración de create-agent","alternativas a create-agent","aprendizaje automático con create-agent","desarrollo de agentes de IA con create-agent"],"fr":["comment créer des agents d''IA","quoi est un agent d''IA","create-agent vs d''autres agents d''IA","installation de create-agent","guide de configuration de create-agent","alternatives à create-agent","apprentissage automatique avec create-agent","développement d''agents d''IA avec create-agent"],"de":["wie man KI-Agents erstellt","was ist ein KI-Agent","create-agent vs andere KI-Agents","Installation von create-agent","Konfigurationsanleitung für create-agent","Alternativen zu create-agent","maschinelles Lernen mit create-agent","Entwicklung von KI-Agents mit create-agent"],"pt":["como criar agentes de ia","create-agent tutorial","agentes de ia personalizados","react e python para ia","node.js para automação","cli para gerenciar agentes de ia","o que é create-agent","create-agent vs outros frameworks"],"ru":["как создать ИИ Агентов","create-agent учебник","индивидуальные ИИ Агенты","react и python для ИИ","node.js для автоматизации","cli для управления ИИ Агентами","что такое create-agent","create-agent vs другие фреймворки"],"ar":["كيفية إنشاء وكلاء الذكاء الاصطناعي","دليل create-agent","وكلاء الذكاء الاصطناعي المخصصين","react و python لإنشاء الذكاء الاصطناعي","node.js للأتمتة","cli لإدارة وكلاء الذكاء الاصطناعي","ما هو create-agent","create-agent مقابل إطارات عمل أخرى"]}},"owner":"zzfancitizen","repo":"agent-skills-self-learning-sample","repoPath":"zzfancitizen/agent-skills-self-learning-sample","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.835Z","topics":[],"category":"community","skillMd":{"name":"create-agent","description":"Scaffold a new agent in this multi-agent system following the project skeleton. Use when the user wants to create, add, or scaffold a new agent, or asks about adding agents to the workflow.","bodyPreview":"# Create Agent\n\nFollow this checklist when creating a new agent. Replace `<name>` with the\nagent name (lowercase, e.g. `reviewer`) and `<Name>` with the PascalCase class\nname (e.g. `ReviewerAgent`).\n\n```\nProgress:\n- [ ] Step 1: Create directory structure\n- [ ] Step 2: Write SKILL.md\n- [ ] Step 3: Write agent.py\n- [ ] Step 4: Write package __init__.py\n- [ ] Step 5: Register in src/agents/__init__.py\n- [ ] Step 6: Add to workflow graph\n- [ ] Step 7: Update router\n- [ ] Step 8: Run verification\n```","body":"# Create Agent\n\nFollow this checklist when creating a new agent. Replace `<name>` with the\nagent name (lowercase, e.g. `reviewer`) and `<Name>` with the PascalCase class\nname (e.g. `ReviewerAgent`).\n\n```\nProgress:\n- [ ] Step 1: Create directory structure\n- [ ] Step 2: Write SKILL.md\n- [ ] Step 3: Write agent.py\n- [ ] Step 4: Write package __init__.py\n- [ ] Step 5: Register in src/agents/__init__.py\n- [ ] Step 6: Add to workflow graph\n- [ ] Step 7: Update router\n- [ ] Step 8: Run verification\n```\n\n## Step 1: Create directory structure\n\n```\nsrc/agents/<name>/\n├── __init__.py\n├── agent.py\n└── skills/\n    └── <skill_name>/\n        ├── SKILL.md\n        └── tools/          # optional, only if agent needs tools\n            ├── __init__.py\n            └── <tool>.py\n```\n\n## Step 2: Write SKILL.md\n\nCreate `src/agents/<name>/skills/<skill_name>/SKILL.md`:\n\n```markdown\n---\nname: <skill_name>\ndescription: Brief description of what this skill does\ntags: [<tag1>, <tag2>]\n---\n\n# <Skill Title>\n\nDetailed instructions the LLM follows when this skill is loaded...\n```\n\n## Step 3: Write agent.py\n\nCreate `src/agents/<name>/agent.py` following this skeleton:\n\n```python\n\"\"\"\n<Name> Agent - <one-line purpose>\n\"\"\"\n\nfrom pathlib import Path\n\nfrom langchain_core.messages import BaseMessage, AIMessage\n\nfrom ..base import BaseAgent\nfrom ...skills.registry import SkillRegistry\nfrom ...skills.loader import SkillLoader\n\n\nclass <Name>Agent(BaseAgent):\n    \"\"\"<Name> Agent — <brief description>\"\"\"\n\n    def __init__(self, skill_registry: SkillRegistry, **kwargs):\n        # Discover and register all skills from skills/ subdirectory\n        agent_dir = Path(__file__).parent\n        skills = SkillLoader.load_agent_skills(agent_dir, lazy=skill_registry._lazy)\n        for skill in skills:\n            skill_registry.register(skill)\n\n        super().__init__(skill_registry, **kwargs)\n\n        # If agent has tools, register them here:\n        # from .skills.<skill_name>.tools.<tool_module> import <tool>\n        # self.register_tools([<tool>])\n\n    @property\n    def agent_name(self) -> str:\n        return \"<Name>Agent\"\n\n    @property\n    def default_skills(self) -> list[str]:\n        return [\"<skill_name>\"]\n\n    @property\n    def base_system_prompt(self) -> str:\n        return \"\"\"<system prompt for this agent>\"\"\"\n\n    def process(self, messages: list[BaseMessage], **kwargs) -> dict:\n        response = self.invoke(messages)\n        content = response.content\n        return {\n            \"result\": content,\n            \"raw_response\": response,\n        }\n```\n\n## Step 4: Write package `__init__.py`\n\nCreate `src/agents/<name>/__init__.py`:\n\n```python\n\"\"\"\n<Name> Agent Package\n\"\"\"\n\nfrom .agent import <Name>Agent\n\n__all__ = [\"<Name>Agent\"]\n```\n\n## Step 5: Register in `src/agents/__init__.py`\n\nAdd the import and export:\n\n```python\nfrom .<name> import <Name>Agent\n```\n\nAnd add `\"<Name>Agent\"` to the `__all__` list.\n\n## Step 6: Add to workflow graph\n\nEdit `src/graph/workflow.py`:\n\n1. **Import** the new agent class in the imports section.\n\n2. **Instantiate** it in `create_workflow()` alongside the other agents:\n   ```python\n   <name> = <Name>Agent(skill_registry, **agent_kwargs)\n   ```\n\n3. **Define a node function** following the existing pattern:\n   ```python\n   def <name>_node(state: AgentState) -> dict:\n       input_data = {\"messages\": state[\"messages\"]}\n       result = <name>.process(state[\"messages\"])\n       output = {\n           \"current_agent\": \"<name>\",\n           # map result keys to AgentState fields as needed\n       }\n       _log_agent(\"<Name>Agent\", input_data, output)\n       return output\n   ```\n\n4. **Register the node**:\n   ```python\n   workflow.add_node(\"<name>\", <name>_node)\n   ```\n\n5. **Add edges** — connect the node to the graph with `add_edge` or\n   `add_conditional_edges` depending on the routing logic.\n\n6. If the new agent''s output needs a new state field, add it to\n   `AgentState` in `src/graph/state.py` and to `create_initial_state()`.\n\n## Step 7: Update router\n\nIf the router should be able to route to this new agent:\n\n1. Add the new route to `RouterAgent.VALID_ROUTES` in\n   `src/agents/router/agent.py`.\n\n2. Add the route description to `RouterAgent.base_system_prompt`.\n\n3. Update `src/agents/router/skills/routing/SKILL.md` with a new section\n   describing when to route to this agent.\n\n4. Update `route_decision()` in `src/graph/workflow.py` to handle the\n   new route value.\n\n## Step 8: Run verification\n\nRun the verification skill to confirm nothing is broken:\n\n```bash\nuv run python -c \"import src.main; import src.graph; import src.agents; import src.skills\"\nuv run python -m src.main --test\n```\n\nExpected: \"Workflow created successfully\", correct skill count, \"All tests passed\".\n"},"lastSynced":"2026-03-04T14:45:18.307Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing structured agent creation with Python and directory management capabilities.","zh":"适合需要使用Python和目录管理功能进行结构化代理创建的AI代理开发人员。","ja":"Pythonとディレクトリ管理機能を使用して構造化されたエージェントを作成する必要があるAIエージェント開発者に最適です。","ko":"Python과 디렉토리 관리 기능을 사용하여 구조화된 에이전트를 생성해야 하는 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Perfecto para desarrolladores de Agentes de IA que necesitan creación de agentes estructurados con Python y capacidades de gestión de directorios.","fr":"Parfait pour les développeurs d''agents IA ayant besoin de création d''agents structurés avec Python et de capacités de gestion de répertoires.","de":"Perfekt für Entwickler von KI-Agents, die eine strukturierte Erstellung von Agents mit Python und Verzeichnisverwaltungsfunktionen benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam de criação de agentes estruturada com Python e capacidades de gerenciamento de diretórios.","ru":"Идеально подходит для разработчиков агентов ИИ, которым необходима структурированная создание агентов с помощью Python и возможностями управления каталогами.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى إنشاء وكلاء منظم مع بايثون وقدرات إدارة الدلائل."},"recommendation":{"en":"Empowers agents to create new directory structures, write skill documentation in Markdown, and implement agent logic in Python using files like agent.py and __init__.py, while integrating with workflow graphs and routers for seamless execution.","zh":"赋予代理创建新的目录结构、使用Markdown编写技能文档、使用Python实现代理逻辑（如agent.py和__init__.py文件），同时与工作流图和路由器集成以实现无缝执行。","ja":"エージェントに新しいディレクトリ構造を作成し、Markdownでスキルドキュメントを書き、Pythonでエージェントロジック（例：agent.pyおよび__init__.pyファイル）を実装し、ワークフローグラフやルーターと統合してシームレスに実行する機能を提供します。","ko":"에이전트가 새로운 디렉토리 구조를 생성하고, 마크다운으로 스킬 문서를 작성하며, 파이썬으로 에이전트 로직(예: agent.py 및 __init__.py 파일)을 구현하고, 워크플로우 그래프 및 라우터와 통합하여 무중단으로 실행할 수 있도록 합니다.","es":"Habilita a los agentes a crear nuevas estructuras de directorios, escribir documentación de habilidades en Markdown y implementar la lógica del agente en Python utilizando archivos como agent.py y __init__.py, mientras se integra con gráficos de flujo de trabajo y enrutadores para una ejecución sin problemas.","fr":"Permet aux agents de créer de nouvelles structures de répertoires, d''écrire la documentation des compétences en Markdown et de mettre en œuvre la logique de l''agent en Python en utilisant des fichiers tels que agent.py et __init__.py, tout en s''intégrant avec des graphiques de workflow et des routeurs pour une exécution sans problème.","de":"Ermöglicht es Agents, neue Verzeichnisstrukturen zu erstellen, Skill-Dokumentationen in Markdown zu schreiben und Agentenlogik in Python mithilfe von Dateien wie agent.py und __init__.py zu implementieren, während es sich in Workflow-Graphen und Router für eine reibungslose Ausführung integriert.","pt":"Habilita os agentes a criar novas estruturas de diretórios, escrever documentação de habilidades em Markdown e implementar lógica de agente em Python usando arquivos como agent.py e __init__.py, enquanto se integra com gráficos de fluxo de trabalho e roteadores para execução sem interrupções.","ru":"Наделяет агентов возможностью создавать новые структуры каталогов, писать документацию умений в Markdown и реализовывать логику агента на Python с помощью файлов seperti agent.py и __init__.py, а также интегрироваться с графами рабочих процессов и маршрутизаторами для бесперебойной работы.","ar":"تمكّن الوكلاء من إنشاء هياكل دلائل جديدة، وكتابة توثيق المهارات في ماركداون، وتنفيذ منطق الوكيل ببايثون باستخدام الملفات مثل agent.py و __init__.py، مع التكامل مع الرسوم البيانية لتدفق العمل والمتحكمات لتنفيذ بدون انقطاع."},"useCases":{"en":["Creating custom agent directory structures","Implementing new agent skills with Python","Registering agents in workflow graphs for automated tasks"],"zh":["创建自定义代理目录结构","使用Python实现新的代理技能","在工作流图中注册代理以实现自动化任务"],"ja":["カスタムエージェントディレクトリ構造を作成する","Pythonで新しいエージェントスキルを実装する","ワークフローグラフにエージェントを登録して自動化タスクを実行する"],"ko":["사용자 지정 에이전트 디렉토리 구조를 생성하는 것","파이썬으로 새로운 에이전트 스킬을 구현하는 것","워크플로우 그래프에 에이전트를 등록하여 자동화된 작업을 수행하는 것"],"es":["Creación de estructuras de directorios de agentes personalizados","Implementación de nuevas habilidades de agentes con Python","Registro de agentes en gráficos de flujo de trabajo para tareas automatizadas"],"fr":["Création de structures de répertoires d''agents personnalisés","Mise en œuvre de nouvelles compétences d''agents avec Python","Enregistrement d''agents dans des graphiques de workflow pour des tâches automatisées"],"de":["Erstellung von benutzerdefinierten Verzeichnisstrukturen für Agents","Implementierung neuer Agentenfähigkeiten mit Python","Registrierung von Agents in Workflow-Graphen für automatisierte Aufgaben"],"pt":["Criação de estruturas de diretórios de agente personalizadas","Implementação de novas habilidades de agente com Python","Registro de agentes em gráficos de fluxo de trabalho para tarefas automatizadas"],"ru":["Создание пользовательских структур каталогов агентов","Реализация новых умений агента с помощью Python","Регистрация агентов в графах рабочих процессов для автоматизированных задач"],"ar":["إنشاء هياكل دلائل وكلاء مخصصة","تنفيذ مهارات وكلاء جديدة ببايثون","تسجيل الوكلاء في الرسوم البيانية لتدفق العمل للمهام الأوتوماتيكية"]},"limitations":{"en":["Requires Python environment","Specific directory structure needed","Manual registration in src/agents/__init__.py required"],"zh":["需要Python环境","需要特定的目录结构","需要在src/agents/__init__.py中手动注册"],"ja":["Python環境が必要","特定のディレクトリ構造が必要","src/agents/__init__.pyに手動で登録する必要がある"],"ko":["파이썬 환경이 필요함","특정 디렉토리 구조가 필요함","src/agents/__init__.py에 수동으로 등록해야 함"],"es":["Requiere entorno de Python","Se requiere una estructura de directorio específica","Se requiere registro manual en src/agents/__init__.py"],"fr":["Nécessite un environnement Python","Une structure de répertoire spécifique est requise","Un enregistrement manuel dans src/agents/__init__.py est requis"],"de":["Benötigt eine Python-Umgebung","Eine spezifische Verzeichnisstruktur ist erforderlich","Eine manuelle Registrierung in src/agents/__init__.py ist erforderlich"],"pt":["Requer ambiente Python","Estrutura de diretório específica necessária","Registro manual em src/agents/__init__.py necessário"],"ru":["Требуется среда Python","Необходима конкретная структура каталога","Требуется ручная регистрация в src/agents/__init__.py"],"ar":["يتطلب بيئة بايثون","هيئة دلائل محددة ضرورية","التسجيل اليدوي في src/agents/__init__.py مطلوب"]},"version":3},"contentHash":"4acde0af0b1643da55b0fc2e9202c851ed36c31a470fb11854768081f8596372","qualityScore":37}');
