INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('VibiumDev/vibium/vibe-check', 'vibe-check', 'VibiumDev', 'vibium', 'community', 'vibe-check VibiumDev vibium community vibe-check 是一个浏览器自动化工具，为 AI 智能体和人类提供高效的开发解决方案 vibe-check は AI エージェントと人間のためのブラウザ自動化ツールであり、高効率の開発ソリューションを提供します vibe-check는 AI 에이전트와 인간을 위한 브라우저 자동화 도구로, 높은 효율의 개발 솔루션을 제공합니다 vibe-check es una herramienta de automatización de navegador para Agentes de Inteligencia Artificial y humanos, que permite agilizar tareas y procesos vibe-check est un outil d''automatisation de navigateur pour Outils d''Intelligence Artificielle et humains, qui permet d''accélérer les tâches et les processus vibe-check ist ein Tool für die Automatisierung von Browser-Aufgaben für KI-Agents und Menschen, das die Beschleunigung von Aufgaben und Prozessen ermöglicht O Vibe-check é uma ferramenta de automação de navegador para agentes de IA e humanos, permitindo a automação de tarefas de navegador Vibe-check - это инструмент автоматизации браузера для ИИ агентов и людей, позволяющий автоматизировать задачи браузера Vibe-check هو أداة آليّة للمتصفح لعمّال الذكاء الاصطناعي والبشر، مما يسمح بالتلقيم المهام المتصفح Browser automation for AI agents and humans 浏览器自动化 AI 智能体 开发解决方案 vibe-check 教程 浏览器自动化工具 AI 工具 开发效率 vibe-check 安装 vibe-check 设置指南 Browser automation for AI agents and humans');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('involvex/vscode-npm-package-manager/vscode-extension-dev', 'community', 'involvex', 'vscode-npm-package-manager', 'involvex/vscode-npm-package-manager', 'vscode-extension-dev', 0, 0, 37, '2026-03-04T13:07:01.921Z', '2026-03-04T15:04:46.678Z', 'd507eb365cec4c5735271a216c3c78b738d66503be339fe633dd4b0353b85e34', '{"id":"involvex/vscode-npm-package-manager/vscode-extension-dev","name":"vscode-extension-dev","description":{"zh":"使用 Node.js 包管理扩展，支持 npm、yarn、pnpm 和 bun，实现高效的包管理","ja":"Node.js パッケージ管理ツールで npm、yarn、pnpm、bun をサポート，高效的包管理を実現","ko":"Node.js 패키지 관리 확장에서 npm, yarn, pnpm, bun을 지원，高效的 패키지 관리를 실현","es":"Desarrolla extensiones de VSCode con Node.js y gestiona paquetes de forma avanzada con npm, yarn, pnpm y bun","fr":"Développez des extensions VSCode avec Node.js et gérez des paquets de manière avancée avec npm, yarn, pnpm et bun","de":"Erstellen Sie VSCode-Erweiterungen mit Node.js und verwalten Sie Pakete auf fortschrittene Weise mit npm, yarn, pnpm und bun","pt":"O vscode-extension-dev oferece gerenciamento avançado de pacotes Node.js com suporte a npm, yarn, pnpm e bun","ru":"ИИ Агент vscode-extension-dev предоставляет расширенное управление пакетами Node.js с поддержкой npm, yarn, pnpm и bun","ar":"يوفر vscode-extension-dev إدارة متقدمة للحزم Node.js مع دعم npm و yarn و pnpm و bun","en":"Advanced Node.js package management with support for npm, yarn, pnpm, and bun"},"seo":{"title":{"zh":"AI智能工具：Node.js包管理扩展","ja":"AIエージェント：Node.jsパッケージ管理ツール","ko":"AI 에이전트：Node.js 패키지 관리 확장","es":"Herramientas de AI: Desarrollo de extensiones de VSCode c...","fr":"Outils d''IA: Développement d''extensions VSCode avec Node.js","de":"KI-Tools: Erweiterungsentwicklung für VSCode mit Node.js","pt":"Ferramentas de Inteligência Artificial para Desenvolvedor...","ru":"ИИ Агенты для Разработчиков: vscode-extension-dev","ar":"أ