INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('snyk/snyk-intellij-plugin/commit', 'commit', 'snyk', 'snyk-intellij-plugin', 'community', 'commit snyk snyk-intellij-plugin community ide-plugin intellij intellij-plugin snyk Snyk Vulnerability Scanner是基于IntelliJ平台的IDE插件，用于扫描代码安全漏洞。该AI智能代理帮助开发者快速识别和修复安全问题 Snyk Vulnerability Scannerは、IntelliJプラットフォーム用のIDEプラグインであり、コードのセキュリティ脆弱性をスキャンします。このAIエージェントは、開発者がセキュリティ問題を迅速に識別して修復するのに役立ちます Snyk 취약점 스キャ너는 IntelliJ 플랫폼용 IDE 플러그인으로 코드의 보안 취약점을 스캔합니다. 이 AI 에이전트는 개발자가 보안 문제를 신속하게 식별하고 수정하는 데 도움을 줍니다 Snyk Vulnerability Scanner es un plugin de seguridad para IDEs basados en IntelliJ que ayuda a detectar vulnerabilidades en tu código Snyk Vulnerability Scanner est un plugin de sécurité pour les IDE basés sur IntelliJ qui aide à détecter les vulnérabilités dans votre code Snyk Vulnerability Scanner ist ein Sicherheits-Plugin für IntelliJ-IDEs, das dabei hilft, Sicherheitslücken in Ihrem Code zu finden A ferramenta de análise de vulnerabilidades Snyk para IDEs é uma solução para detectar e corrigir vulnerabilidades de segurança no seu código. Сканер уязвимостей Snyk для IntelliJ - это решение для обнаружения и исправления уязвимостей безопасности в вашем коде, ИИ Агенты أداة فحص الثغرات الأمنية Snyk لتحميل المطورين هي حل لاكتشاف وتحسين الثغرات الأمنية في رمزك Snyk Vulnerability Scanner for IDEs based on the IntelliJ platform Snyk Vulnerability Scanner IntelliJ插件 代码安全扫描 AI智能代理 如何使用Snyk Snyk与其他工具的比较 Snyk安装指南 IntelliJ安全插件 Snyk Vulnerability Scanner for IDEs based on the IntelliJ platform');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ahtavarasmus/lightfriend/lightfriend-add-frontend-page', 'community', 'ahtavarasmus', 'lightfriend', 'ahtavarasmus/lightfriend', 'lightfriend-add-frontend-page', 65, 7, 36, '2026-03-03T12:30:29Z', '2026-03-03T13:07:30.095Z', '10ff422199a4619a2e57bebe9df7c935ecd7a1d0cf63d669994ce6e62e3fed0f', '{"id":"ahtavarasmus/lightfriend/lightfriend-add-frontend-page","name":"lightfriend-add-frontend-page","description":{"zh":"AI智能助手轻松添加前端页面，帮助dumphone用户提高开发效率","ja":"AIエージェントによるフロントエンドページの追加は、開発効率を向上させます","ko":"AI 에이전트를 사용한 프론트엔드 페이지 추가는 개발 효율성을 높여줍니다","es":"lightfriend-add-frontend-page es una herramienta de AI para mejorar la experiencia de los usuarios de dumbphone","fr":"lightfriend-add-frontend-page est un outil d''IA pour améliorer l''expérience des utilisateurs de dumbphone","de":"lightfriend-add-frontend-page ist ein KI-Tool, um die Erfahrung von Dumbphone-Nutzern zu verbessern","pt":"A lightfriend-add-frontend-page é uma ferramenta de AI que ajuda desenvolvedores a criar páginas frontend para usuários de dumphone de forma eficiente","ru":"ИИ Агент lightfriend-add-frontend-page помогает разработчикам создавать frontend-страницы для пользователей dumphone эффективно","ar":"أداة الذكاء الاصطناعي lightfriend-add-frontend-page تساعد المطورين على إنشاء صفحات واجهة المستخدم الأمامية ل مستخدمي dumphone بطريقة فعالة","en":"AI Assistant for dumphone users"},"seo":{"title":{"zh":"AI智能助手轻松添加前端页面","ja":"AIエージェントによるフロントエンドページの追加","ko":"AI 에이전트를 사용한 프론트엔드 페이지 추가","es":"Herramientas de AI: lightfriend-add-frontend-page para us...","fr":"Outils d''IA: lightfriend-add-frontend-page pour les utili...","de":"KI-Tools: lightfriend-add-frontend-page für Dumbphone-Nutzer","pt":"Ferramenta de AI para Desenvolvedores: lightfriend-add-fr...","ru":"ИИ Агенты для разработчиков: lightfriend-add-frontend-page","ar":"أداة الذكاء الاصطناعي لل