INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MatrixReligio/ProductVideoCreator/bgm', 'bgm', 'MatrixReligio', 'ProductVideoCreator', 'community', 'bgm MatrixReligio ProductVideoCreator community AI智能工具bgm是一个自动化产品介绍视频生成工具，使用Remotion、Playwright和edge-tts技术，帮助开发者提高效率 AIエージェントbgmは、Remotion、Playwright、edge-ttsを使用した自動化製品紹介動画生成ツールです。開発者の効率化を支援 AI 에이전트bgm는 Remotion, Playwright, edge-tts를 사용한 자동화 제품 소개 비디오 생성 도구입니다. 개발자의 효율성을 향상 Nuestra herramienta de AI Agent utiliza Remotion, Playwright y edge-tts para generar vídeos de introducción de productos de manera automática Notre outil d''Agent IA utilise Remotion, Playwright et edge-tts pour générer des vidéos d''introduction de produits de manière automatique Unser AI-Agent-Tool verwendet Remotion, Playwright und edge-tts, um Produkt-Einführungs-Videos automatisch zu generieren O bgm é uma ferramenta de agente de IA para geração automática de vídeos de introdução de produtos utilizando Remotion, Playwright e edge-tts. ИИ Агент bgm предназначен для автоматизированного видеовведения продуктов с использованием Remotion, Playwright и edge-tts. وكلاء الذكاء الاصطناعي bgm هي أداة لمساعدتك في توليد مقاطع فيديو تعريف المنتجات آليًا باستخدام Remotion و Playwright و edge-tts AI Agent Skills toolkit for automated product introduction video generation with Remotion, Playwright, and edge-tts AI智能工具 自动化产品介绍视频生成 Remotion Playwright edge-tts 如何使用bgm bgm安装指南 bgm替代品 AI Agent Skills toolkit for automated product introduction video generation with Remotion, Playwright, and edge-tts');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaredpalmer/agentik/code-reviewer', 'community', 'jaredpalmer', 'agentik', 'jaredpalmer/agentik', 'code-reviewer', 17, 1, 36, '2026-02-22T15:53:09Z', '2026-02-26T13:21:13.085Z', '6b868599d2daabc3287ffe20a03350f4a51fccc029a80541a37bd823d047b364', '{"id":"jaredpalmer/agentik/code-reviewer","name":"code-reviewer","description":{"zh":"Composable AI Agent Runtime是一款代码审查AI代理，帮助开发者简化代码审查流程，提升代码质量","ja":"AIエージェントランタイムは、開発者がコードレビューのプロセスを簡素化し、コードの品質を向上させるのに役立つコードレビューアイゼントです","ko":"Composable AI 에이전트 런타임은 코드 리뷰 AI 에이전트로서 개발자가 코드 리뷰 프로세스를 간소화하고 코드 품질을 향상시키는 데 도움을 줍니다","es":"El entorno de ejecución componible para agentes de inteligencia artificial permite una integración flexible y escalable en tus proyectos de desarrollo.","fr":"L''environnement d''exécution composable pour les agents d''intelligence artificielle permet une intégration flexible et évolutives dans vos projets de développement.","de":"Die komponierbare Laufzeit für KI-Agents ermöglicht eine flexible und skalierbare Integration in Ihre Entwicklungsvorhaben.","pt":"O Code Reviewer é um runtime de agente de IA composto para desenvolvedores, permitindo a integração de AI em projetos de forma eficiente","ru":"Code Reviewer - это комposable ИИ агент runtime для разработчиков, позволяющий интегрировать ИИ в проекты эффективно","ar":"محرر الشفرة هو وقت تشغيل وكلاء الذكاء الاصطناعي القابل للتركيب للمطورين، يسمح بإضافة الذكاء الاصطناعي إلى المشاريع بفعالية","en":"Composable AI agent runtime"},"seo":{"title":{"zh":"代码审查AI代理 - Composable AI Agent Runtime","ja":"AIエージェントランタイム - コードレビューアイゼント","ko":"코드 리뷰 AI 에이전트 - Composable AI 에이전트 런타임","es":"Revisador de código AI: Entorno de ejecución componible","fr":"Code Reviewer AI : Runtime composable","de":"Code-Reviewer KI: Komponierbare Laufzeit","pt":"Ferramentas de AI Agents: Code Reviewer","ru":"ИИ Агенты: Code Reviewer для разработчиков","ar":"أدوات وكلاء الذكاء الاصطناعي: محرر الشفرة","en":"code-reviewer"},"description":{"zh":"Composable AI Agent Runtime是一款代码审查AI代理，帮助开发者简化代码审查流程，提升代码质量","ja":"AIエージェントランタイムは、開発者がコードレビューのプロセスを簡素化し、コードの品質を向上させるのに役立つコードレビューアイゼントです","ko":"Composable AI 에이전트 런타임은 코드 리뷰 AI 에이전트로서 개발자가 코드 리뷰 프로세스를 간소화하고 코드 품질을 향상시키는 데 도움을 줍니다","es":"El entorno de ejecución componible para agentes de inteligencia artificial permite una integración flexible y escalable en tus proyectos de desarrollo.","fr":"L''environnement d''exécution composable pour les agents d''intelligence artificielle permet une intégration flexible et évolutives dans vos projets de développ...","de":"Die komponierbare Laufzeit für KI-Agents ermöglicht eine flexible und skalierbare Integration in Ihre Entwicklungsvorhaben.","pt":"O Code Reviewer é um runtime de agente de IA composto para desenvolvedores, permitindo a integração de AI em projetos de forma eficiente","ru":"Code Reviewer - это комposable ИИ агент runtime для разработчиков, позволяющий интегрировать ИИ в проекты эффективно","ar":"محرر الشفرة هو وقت تشغيل وكلاء الذكاء الاصطناعي القابل للتركيب للمطورين، يسمح بإضافة الذكاء الاصطناعي إلى المشاريع بفعالية","en":"Composable AI agent runtime"},"definition":{"en":"Composable AI agent runtime"},"features":{"zh":["自动代码审查","代码质量分析","实时反馈","集成开发环境支持","多语言支持"],"ja":["自動コードレビュー","コード品質分析","リアルタイムフィードバック","統合開発環境サポート","多言語サポート"],"ko":["자동 코드 리뷰","코드 품질 분석","실시간 피드백","통합 개발 환경 지원","다중 언어 지원"],"es":["Entorno de ejecución componible","Integración flexible con proyectos de desarrollo","Escalabilidad y flexibilidad","Soporte para múltiples lenguajes de programación","Interfaz de línea de comandos (CLI) intuitiva"],"fr":["Environnement d''exécution composable","Intégration flexible avec les projets de développement","Évolutivité et flexibilité","Support pour plusieurs langages de programmation","Interface de ligne de commande (CLI) intuitive"],"de":["Komponierbare Laufzeit","Flexible Integration in Entwicklungsvorhaben","Skalierbarkeit und Flexibilität","Unterstützung für mehrere Programmiersprachen","Intuitive Kommandozeilen-Schnittstelle (CLI)"],"pt":["Integração de AI em projetos","Runtime de agente de IA composto","Desenvolvimento de software com IA","Ferramentas de desenvolvedor para AI","Suporte a linguagens de programação como Python e Node.js"],"ru":["Интеграция ИИ в проекты","Комposable ИИ агент runtime","Разработка программного обеспечения с ИИ","Инструменты для разработчиков ИИ","Поддержка языков программирования như Python и Node.js"],"ar":["دمج الذكاء الاصطناعي في المشاريع","وقت تشغيل وكلاء الذكاء الاصطناعي القابل للتركيب","تطوير البرمجيات بالذكاء الاصطناعي","أدوات المطورين للذكاء الاصطناعي","دعم لغات البرمجة مثل Python و Node.js"]},"keywords":{"zh":["代码审查AI代理","如何使用代码审查AI代理","代码审查AI代理替代品","代码审查AI代理与其他工具的比较","代码审查AI代理安装","代码审查AI代理设置指南","AI代码审查工具","代码质量分析工具"],"ja":["AIエージェントランタイム","AIエージェントランタイムの使い方","AIエージェントランタイムの代替","AIエージェントランタイムと他のツールの比較","AIエージェントランタイムのインストール","AIエージェントランタイムの設定ガイド","AIコードレビューツール","コード品質分析ツール"],"ko":["코드 리뷰 AI 에이전트","코드 리뷰 AI 에이전트 사용법","코드 리뷰 AI 에이전트 대체품","코드 리뷰 AI 에이전트와 다른 도구의 비교","코드 리뷰 AI 에이전트 설치","코드 리뷰 AI 에이전트 설정 가이드","AI 코드 리뷰 도구","코드 품질 분석 도구"],"es":["cómo utilizar agentes de inteligencia artificial","qué es un agente de inteligencia artificial","entorno de ejecución componible","alternativas a los agentes de inteligencia artificial","instalación de agentes de inteligencia artificial","guía de configuración de agentes de inteligencia artificial","desarrollo de aplicaciones con agentes de inteligencia artificial"],"fr":["comment utiliser les agents d''intelligence artificielle","qu''est-ce qu''un agent d''intelligence artificielle","environnement d''exécution composable","alternatives aux agents d''intelligence artificielle","installation des agents d''intelligence artificielle","guide de configuration des agents d''intelligence artificielle","développement d''applications avec les agents d''intelligence artificielle"],"de":["wie man KI-Agents verwendet","was ist ein KI-Agent","komponierbare Laufzeit","Alternativen zu KI-Agents","Installation von KI-Agents","Konfigurationsanleitung für KI-Agents","Entwicklung von Anwendungen mit KI-Agents"],"pt":["como usar AI em projetos","o que é agente de IA","ferramentas de AI para desenvolvedores","Code Reviewer alternative","instalar Code Reviewer","guias de configuração do Code Reviewer","desenvolvimento de software com AI","IA em projetos de desenvolvimento"],"ru":["как использовать ИИ в проектах","что такое ИИ агент","инструменты ИИ для разработчиков","Code Reviewer альтернатив","установить Code Reviewer","руководства по настройке Code Reviewer","разработка программного обеспечения с ИИ","ИИ в проектах разработки"],"ar":["كيفية استخدام الذكاء الاصطناعي في المشاريع","ما هو وكيل الذكاء الاصطناعي","أدوات الذكاء الاصطناعي للمطورين","بديل محرر الشفرة","تثبيت محرر الشفرة","دليل إعداد محرر الشفرة","تطوير البرمجيات بالذكاء الاصطناعي","الذكاء الاصطناعي في مشاريع التطوير"]}},"owner":"jaredpalmer","repo":"agentik","repoPath":"jaredpalmer/agentik","stars":17,"forks":1,"updatedAt":"2026-02-22T15:53:09Z","topics":["agents","ai","ai-sdk"],"category":"community","skillMd":{"name":"code-reviewer","description":"Review code for adherence to project guidelines, style guides, and best practices. Use after writing or modifying code, especially before committing changes or creating pull requests.","bodyPreview":"# Code Reviewer Skill\n\n## When to Use This Skill\n\n- After implementing a feature or logical chunk of code.\n- After writing a utility function or refactor.\n- Before creating or finalizing a pull request.\n- When you need a focused review of a specific set of files (default: `git diff`).\n\n## Examples\n\n**Context:** The user has just implemented a new feature with several TypeScript files.\n**User:** \"I''ve added the new authentication feature. Can you check if everything looks good?\"\n**Assistant:** \"I","body":"# Code Reviewer Skill\n\n## When to Use This Skill\n\n- After implementing a feature or logical chunk of code.\n- After writing a utility function or refactor.\n- Before creating or finalizing a pull request.\n- When you need a focused review of a specific set of files (default: `git diff`).\n\n## Examples\n\n**Context:** The user has just implemented a new feature with several TypeScript files.\n**User:** \"I''ve added the new authentication feature. Can you check if everything looks good?\"\n**Assistant:** \"I''ll use the code-reviewer skill to review your recent changes.\"\n\n**Context:** The assistant has just written a new utility function.\n**User:** \"Please create a function to validate email addresses\"\n**Assistant:** \"Here''s the email validation function. Now I''ll use the code-reviewer skill to review this implementation.\"\n\n**Context:** The user is about to create a PR.\n**User:** \"I think I''m ready to create a PR for this feature\"\n**Assistant:** \"Before creating the PR, I''ll use the code-reviewer skill to ensure all code meets our standards.\"\n\nYou are an expert code reviewer specializing in modern software development across multiple languages and frameworks. Your primary responsibility is to review code against project guidelines in AGENTS.md with high precision to minimize false positives.\n\n## Review Scope\n\nBy default, review unstaged changes from `git diff`. The user may specify different files or scope to review.\n\n## Core Review Responsibilities\n\n**Project Guidelines Compliance**: Verify adherence to explicit project rules (typically in AGENTS.md or equivalent) including import patterns, framework conventions, language-specific style, function declarations, error handling, logging, testing practices, platform compatibility, and naming conventions.\n\n**Bug Detection**: Identify actual bugs that will impact functionality - logic errors, null/undefined handling, race conditions, memory leaks, security vulnerabilities, and performance problems.\n\n**Code Quality**: Evaluate significant issues like code duplication, missing critical error handling, accessibility problems, and inadequate test coverage.\n\n## Issue Confidence Scoring\n\nRate each issue from 0-100:\n\n- **0-25**: Likely false positive or pre-existing issue\n- **26-50**: Minor nitpick not explicitly in AGENTS.md\n- **51-75**: Valid but low-impact issue\n- **76-90**: Important issue requiring attention\n- **91-100**: Critical bug or explicit AGENTS.md violation\n\n**Only report issues with confidence ≥ 80**\n\n## Output Format\n\nStart by listing what you''re reviewing. For each high-confidence issue provide:\n\n- Clear description and confidence score\n- File path and line number\n- Specific AGENTS.md rule or bug explanation\n- Concrete fix suggestion\n\nGroup issues by severity (Critical: 90-100, Important: 80-89).\n\nIf no high-confidence issues exist, confirm the code meets standards with a brief summary.\n\nBe thorough but filter aggressively - quality over quantity. Focus on issues that truly matter.\n"},"lastSynced":"2026-02-26T13:21:13.085Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing thorough code examination and validation.","zh":"非常适合需要彻底代码检查和验证的开发代理。","ja":"開発エージェントが徹底的なコードの検査と検証を必要とする場合に最適です。","ko":"개발 에이전트가 철저한 코드 검사 및 검증을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un examen y validación de código exhaustivos.","fr":"Parfait pour les agents de développement qui ont besoin d''un examen et de validation de code approfondis.","de":"Perfect für Entwicklungsagenten, die eine gründliche Codeprüfung und -validierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de um exame e validação de código aprofundados.","ru":"Идеально подходит для агентов разработки, которым требуется тщательный анализ и проверка кода.","ar":"مثالي للوكلاء النموزجيون الذين يحتاجون إلى فحص شاملاً للتحقق من صحة الكود."},"recommendation":{"en":"Empowers agents to scrutinize TypeScript files, perform git diff analysis, and provide focused reviews of specific code sets, ensuring adherence to best practices and identifying potential bugs or security vulnerabilities.","zh":"赋予代理检查TypeScript文件、执行git diff分析和提供特定代码集的专注审查的能力，确保遵循最佳实践并识别潜在的错误或安全漏洞。","ja":"TypeScriptファイルのチェック、git diff分析の実行、および特定のコードセットの集中レビューを提供することで、エージェントを強化し、ベストプラクティスの遵守と潜在的なバグまたはセキュリティ脆弱性の特定を保証します。","ko":"TypeScript 파일을 검사하고 git diff 분석을 수행하며 특정 코드 세트에 대한 집중적인 리뷰를 제공함으로써 에이전트를 강화하여 beste 실践을 준수하고 잠재적인 버그 또는 보안 취약성을 식별합니다.","es":"Empodera a los agentes para que examinen archivos TypeScript, realicen un análisis de git diff y proporcionen revisiones enfocadas de conjuntos de código específicos, garantizando que se adhieran a las mejores prácticas y identificando posibles bugs o vulnerabilidades de seguridad.","fr":"Empodera a los agentes para que examinen archivos TypeScript, realicen un análisis de git diff y proporcionen revisiones enfocadas de conjuntos de código específicos, garantizando que se adhieran a las mejores prácticas y identificando posibles bugs o vulnerabilidades de seguridad.","de":"Empodera a los agentes para que examinen archivos TypeScript, realicen un análisis de git diff y proporcionen revisiones enfocadas de conjuntos de código específicos, garantizando que se adhieran a las mejores prácticas y identificando posibles bugs o vulnerabilidades de seguridad.","pt":"Habilita os agentes a examinar arquivos TypeScript, realizar análise de git diff e fornecer revisões focadas de conjuntos de código específicos, garantindo a adesão às melhores práticas e identificando possíveis bugs ou vulnerabilidades de segurança.","ru":"Позволяет агентам изучать файлы TypeScript, выполнять анализ git diff и предоставлять сосредоточенные обзоры конкретных наборов кода, гарантируя соблюдение最佳 практик и выявление потенциальных ошибок или уязвимостей безопасности.","ar":"تمكين الوكلاء من فحص ملفات TypeScript، وإجراء تحليل git diff، وتقديم استعراضات محددة لمجموعات الكود الخاصة، مما يضمن الالتزام بأفضل الممارسات وتحديد الأخطاء المحتملة أو نقاط الضعف في الأمن."},"useCases":{"en":["Reviewing feature implementations","Validating utility functions","Debugging code refactors","Inspecting pull requests before finalization"],"zh":["审查功能实现","验证实用函数","调试代码重构","在最终确定之前检查拉取请求"],"ja":["機能の実装のレビュー","ユーティリティ関数の検証","コードのリファクタリングのデバッグ","最終決定前にプルリクエストの検査"],"ko":["기능 구현 리뷰","유틸리티 함수 검증","코드 리팩토링 디버깅","최종 결정 전에 풀 요청 검사"],"es":["Revisar implementaciones de características","Validar funciones de utilidad","Depurar refactorizaciones de código","Inspeccionar solicitudes de pull antes de la finalización"],"fr":["Réviser les implementations de fonctionnalités","Valider les fonctions de utilité","Déboguer les refactorisations de code","Inspeccionar les demandes de pull avant la finalisation"],"de":["Revisar Implementierungen von Funktionen","Validar Funktionen von Utilität","Depurar Refactorizaciones de Code","Inspeccionar Pull-Anfragen vor der Finalisierung"],"pt":["Revisão de implementações de recursos","Validação de funções de utilidade","Depuração de refatorações de código","Inspeção de solicitações de pull antes da finalização"],"ru":["Просмотр реализаций функций","Проверка функций утилиты","Отладка рефакторинга кода","Осмотр запросов на слияние перед их завершением"],"ar":["استعراض تنفيذ الميزات","تحقق من دوال الفائدة","تصحيح الأخطاء في إعادة هيكلة الكود","تفتيش طلبات السحب قبل الإنهاء"]},"limitations":{"en":["Requires access to git repository","Limited to reviewing code in specific formats (e.g., TypeScript)"],"zh":["需要访问git仓库","仅限于检查特定格式的代码（例如TypeScript）"],"ja":["gitリポジトリへのアクセスが必要","特定の形式（例：TypeScript）のコードのみをレビュー可能"],"ko":["git 저장소에 대한 액세스가 필요함","특정 형식(예: TypeScript)의 코드만 검토 가능"],"es":["Requiere acceso al repositorio de git","Limitado a revisar código en formatos específicos (por ejemplo, TypeScript)"],"fr":["Requiere acceso al répertoire de git","Limitado a revisar código en formatos spécifiques (par exemple, TypeScript)"],"de":["Requiere acceso al Git-Repository","Limitado a revisar código en formatos específicos (por ejemplo, TypeScript)"],"pt":["Requer acesso ao repositório git","Limitado à revisão de código em formatos específicos (por exemplo, TypeScript)"],"ru":["Требуется доступ к репозиторию git","Ограничен просмотром кода в конкретных форматах (например, TypeScript)"],"ar":["يتطلب الوصول إلى مستودع git","محدود بالاستعراض الكود في صيغ محددة (على سبيل المثال، TypeScript)"]},"version":3},"contentHash":"6b868599d2daabc3287ffe20a03350f4a51fccc029a80541a37bd823d047b364","qualityScore":36}');
