INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gmh5225/awesome-web3-security/mev-security', 'mev-security', 'gmh5225', 'awesome-web3-security', 'community', 'mev-security gmh5225 awesome-web3-security community security web3 mev安全是一个为Web3安全测试人员和漏洞狩猎者提供的资源和材料集合 mevセキュリティは、Web3セキュリティテスターとバグハンターのためのリソースと資料のキュレーションです mev 보안은 Web3 보안 테스터와 버그 헌터를 위한 리소스와 자료의 컬렉션입니다 Recursos y materiales de seguridad Web3 para pentesters y cazadores de bugs Ressources et matériels de sécurité Web3 pour les testeurs de pénétration et les chasseurs de bugs Ressourcen und Materialien für Web3-Sicherheit für Penetrationstester und Bug-Jäger A mev-security é uma lista curada de materiais e recursos de segurança Web3 para pentesters e caçadores de bugs. mev-security - это курированная коллекция материалов и ресурсов по безопасности Web3 для пентестеров и хантеров багов. mev-security هي قائمة من الموارد والمواد المتعلقة بأمان الويب 3 لمحترفي الاختبار والبحث عن الثغرات. A curated list of Web3 Security materials and resources for Pentesters and Bug Hunters. 如何使用mev安全 什么是Web3安全 mev安全替代品 mev安全与其他工具的比较 mev安全安装 Web3安全测试教程 漏洞狩猎技巧 AI智能代理安全 A curated list of Web3 Security materials and resources for Pentesters and Bug Hunters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cjprybol/Mycelia/julia-style', 'community', 'cjprybol', 'Mycelia', 'cjprybol/Mycelia', 'julia-style', 0, 0, 36, '2026-02-28T01:32:52.530Z', '2026-02-28T02:15:17.145Z', '770ba80670fa4e052c42a5480a09c41937c5fc75aa8d6f26565300fb8568a7b4', '{"id":"cjprybol/Mycelia/julia-style","name":"julia-style","description":{"zh":"Julia风格多组学分析和数据集成，用于生物特性表征、预测和设计","ja":"Juliaスタイルのマルチオミクス解析とデータ統合","ko":"Julia 스타일 멀티오믹스 분석 및 데이터 통합","es":"julia-style es una herramienta de análisis multiómico para la caracterización, predicción y diseño biológico","fr":"julia-style est un outil d''analyse multiomique pour la caractérisation, la prédiction et la conception biologique","de":"julia-style ist ein Tool für die multiomische Analyse zur Charakterisierung, Vorhersage und zum Design biologischer Systeme","pt":"O julia-style é uma ferramenta de IA em desenvolvimento para análise multiômica e integração de dados, projetada para sistemas HPC e cloud linux","ru":"julia-style - это ИИ Агент в разработке для мультиомического анализа и интеграции данных, предназначенный для linux-систем HPC и облака","ar":"جوليا-ستايل هو أداة ذكاء اصطناعي قيد التطوير للتحليل المульتومي وتكامل البيانات، مصممة لأنظمة لينكس HPC وسحابة","en":"In Development: Multiomic analysis and data integration for biological characterization, prediction, and  design. Designed for linux-based HPC and cloud systems."},"seo":{"title":{"zh":"AI智能工具：Julia风格多组学分析","ja":"AIエージェント：Juliaスタイルのマルチオミクス解析","ko":"AI 에이전트: Julia 스타일 멀티오믹스 분석","es":"Herramientas de AI: Análisis multiómico con julia-style","fr":"Outils d''IA: Analyse multiomique avec julia-style","de":"KI-Tools: Multiomische Analyse mit julia-style","pt":"Ferramentas de IA: julia-style para Análise Multiômica","ru":"ИИ Агенты: julia-style для Мультиомического Анализа","ar":"أدوات الذكاء الاصطناعي: julia-style للتحليل المульت