INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('breferrari/obsidian-mind/obsidian-cli', 'obsidian-cli', 'breferrari', 'obsidian-mind', 'community', 'obsidian-cli breferrari obsidian-mind community Obsidian CLI 是一个为工程师提供的 Obsidian Vault 模板，用于与 Claude Code AI 工具合作，提高开发效率 Obsidian CLI はエンジニア向けの Obsidian Vault テンプレートで、Claude Code AI エージェントと協力して開発を効率化します Obsidian CLI는 엔지니어를 위한 Obsidian Vault 템플릿으로, Claude Code AI 에이전트와 협력하여 개발을 효율화합니다 Obsidian-cli es un template de vault para ingenieros que utilizan Claude Code. Ofrece una integración perfecta para el desarrollo de proyectos Obsidian-cli est un modèle de vault pour les ingénieurs qui utilisent Claude Code. Il offre une intégration parfaite pour le développement de projets Obsidian-cli ist ein Vault-Template für Ingenieure, die Claude Code verwenden. Es bietet eine perfekte Integration für die Entwicklung von Projekten O Obsidian-CLI é um modelo de vault para engenheiros que usam Claude Code como parceiro de pensamento, permitindo a integração de IA na rotina de desenvolvimento. Obsidian-CLI - это шаблон хранилища для инженеров, которые используют Claude Code в качестве партнера для мышления, позволяющий интегрировать ИИ в разработку. Obsidian-CLI هو نموذج خزانة لمهندسي البرمجيات الذين يستخدمون Claude Code كشريك في التفكير، مما يسمح بدمج الذكاء الاصطناعي في روتين التطوير. An Obsidian vault template for engineers who use Claude Code as a thinking partner. Obsidian CLI AI 工具 Claude Code 开发效率 代码管理 Obsidian Vault AI 工具模板 如何使用 Obsidian CLI Obsidian CLI 教程 An Obsidian vault template for engineers who use Claude Code as a thinking partner.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('uukuguy/claude-agent-framework/PDF 工具集', 'community', 'uukuguy', 'claude-agent-framework', 'uukuguy/claude-agent-framework', 'PDF 工具集', 0, 0, 36, '2025-12-27T20:17:49Z', '2026-02-26T13:09:04.713Z', '02e1a382a35b788295b674d07bc32c97df62dd495c4dcd6e6aca01f88cfd52f0', '{"id":"uukuguy/claude-agent-framework/PDF 工具集","name":"PDF 工具集","description":{"zh":"PDF 工具集是一个生产就绪的多代理编排框架，基于 Claude Agent SDK，用于设计、编排和部署复杂的 AI 工作流","ja":"PDF ツールキットは、Claude Agent SDK に基づく生産就緒のマルチエージェントオーケストレーションフレームワークで、複雑な AI ワークフローの設計、作成、デプロイに使用されます","ko":"PDF 도구 모음은 Claude Agent SDK를 기반으로 하는 생산 준비 멀티 에이전트 오케스트레이션 프레임워크로서 복잡한 AI 워크플로우의 설계, 구성, 배포에 사용","es":"El PDF 工具集 es un framework de orquestación de agentes multi-para la creación de flujos de trabajo complejos con patrones de arquitectura preconstruidos","fr":"Le PDF 工具集 est un framework d''orchestration d''agents multi- pour la création de flux de travail complexes avec des modèles d''architecture préconstruits","de":"Das PDF 工具集 ist ein Framework für die Orchestrierung von Multi-Agenten zur Erstellung komplexer Workflows mit vorkonfigurierten Architekturmuster","pt":"O PDF 工具集 é um framework de orquestração de múltiplos agentes para designers e desenvolvedores. Ele permite criar workflows de AI complexos com padrões de arquitetura pré-construídos.","ru":"PDF 工具集 - производственный фреймворк для оркестровки нескольких агентов. Он позволяет разработчикам создавать сложные рабочие процессы ИИ с предварительно построенными шаблонами архитектуры.","ar":"PDF 工具集 هو إطار عمل لتنسيق متعدد الوكلاء للتصميم والتطوير. يسمح للمطورين بإنشاء تدفقات عمل ذكاء اصطناعي معقدة مع أنماط بنية مُسبقة البناء.","en":"A production-ready multi-agent orchestration framework built on Claude Agent SDK. Design, compose, and deploy complex AI workflows with pre-built architecture patterns."},"seo":{"title":{"zh":"AI 工