INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SudoMaker/rEFui/refui', 'refui', 'SudoMaker', 'rEFui', 'community', 'refui SudoMaker rEFui community Refui是一个JavaScript框架，用于构建跨 web、native 和嵌入式UI项目，提高开发效率 Refuiは、Web、ネイティブ、埋め込みUIプロジェクトを構築するためのJavaScriptフレームワークです Refui는 웹, 네이티브, 임베디드 UI 프로젝트를 구축하기 위한 JavaScript 프레임워크입니다 Refui es un framework JavaScript que acelera el desarrollo de proyectos UI en diferentes plataformas. Ofrece una solución integral para crear interfaces de usuario innovadoras Refui est un framework JavaScript qui accélère le développement de projets UI sur différentes plateformes. Il offre une solution complète pour créer des interfaces utilisateur innovantes Refui ist ein JavaScript-Framework, das die Entwicklung von UI-Projekten auf verschiedenen Plattformen beschleunigt. Es bietet eine umfassende Lösung zur Erstellung von innovativen Benutzeroberflächen Refui é um framework JavaScript que facilita a criação de projetos de UI em web, nativo e embarcado Refui - это фреймворк JavaScript, который упрощает разработку проектов UI для веба, натива и встраиваемых систем Refui هو إطار عمل JavaScript يسهل إنشاء مشاريع واجهة المستخدم على الويب والأصلية والمضمنة The JavaScript framework that refuels your UI projects, across web, native, and embedded Refui AI智能UI框架 JavaScript框架 UI开发 跨平台支持 如何使用Refui Refui安装 Refui设置指南 The JavaScript framework that refuels your UI projects, across web, native, and embedded');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heroui-inc/heroui/heroui-react', 'community', 'heroui-inc', 'heroui', 'heroui-inc/heroui', 'heroui-react', 0, 0, 36, '2026-03-04T13:07:01.672Z', '2026-03-04T13:22:59.494Z', '677bc9af34543cfa9f111125f8cadfdbdd5d2a958d75aa01605fccf5b6946e92', '{"id":"heroui-inc/heroui/heroui-react","name":"heroui-react","description":{"zh":"heroui-react是快速、现代的React UI库，帮助您快速构建React应用","ja":"heroui-reactは高速でモダンなReact UIライブラリで、Reactアプリの構築を迅速化","ko":"heroui-react는 빠르고 현대적인 리액트 UI 라이브러리로서 리액트 애플리케이션을 빠르게 구축","es":"heroui-react es una biblioteca UI de React rápida y moderna para desarrolladores","fr":"heroui-react est une bibliothèque UI React rapide et moderne pour les développeurs","de":"heroui-react ist eine schnelle und moderne React-UI-Bibliothek für Entwickler","pt":"A heroui-react é uma biblioteca UI React moderna e rápida, previamente conhecida como NextUI. Ela fornece componentes de interface do usuário bonitos e personalizáveis.","ru":"heroui-react - это современная и быстрая библиотека UI для React, ранее известная как NextUI. Она предоставляет красивые и настраиваемые компоненты интерфейса пользователя.","ar":"heroui-react هي مكتبة واجهة مستخدم رياكت الحديثة والسريعة، كانت تُعرف سابقًا باسم NextUI. توفر مكونات واجهة مستخدم جميلة وقابلة للتعديل.","en":"🚀 Beautiful, fast and modern React UI library. (Previously NextUI)"},"seo":{"title":{"zh":"heroui-react：快速现代的React UI库","ja":"heroui-react：高速でモダンなReact UIライブラリ","ko":"heroui-react: 빠르고 현대적인 리액트 UI 라이브러리","es":"Herramientas de AI: heroui-react, biblioteca UI de React","fr":"Outils IA: heroui-react, bibliothèque UI React","de":"KI-Tools: heroui-react, React UI-Bibliothek","pt":"heroui-react: Biblioteca UI React Moderna e Rápida - Ferr...","ru":"heroui-react: Красивая, быстрая и современная библиотека ...","ar":"heroui-react: مكتبة واجهة مستخدم رياكت الحديثة والسريعة -...",