INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sylin-org/koan-framework/koan-performance', 'koan-performance', 'sylin-org', 'koan-framework', 'community', 'koan-performance sylin-org koan-framework community Koan是一个现代的、模块化的.NET 10框架，用于构建复杂应用，具有简单的模式和AI集成 Koanは、シンプルなパターンとAI統合を備えた、モダンでモジュラーな.NET 10フレームワークです Koan은 단순한 패턴과 AI 통합을 갖춘 현대적인 모듈러 .NET 10 프레임워크입니다 Koan es un framework .NET 10 moderno y modular que permite a equipos pequeños construir aplicaciones sofisticadas con patrones simples Koan est un framework .NET 10 moderne et modulaire qui permet aux équipes petites de construire des applications sophistiquées avec des modèles simples Koan ist ein modernes, modulares .NET 10-Framework, das es kleinen Teams ermöglicht, komplexe Anwendungen mit einfachen Mustern zu erstellen Koan é um framework moderno e modular para .NET 10 que facilita a criação de aplicações sofisticadas com padrões simples Koan - современный и модульный фреймворк для .NET 10, который упрощает создание сложных приложений с простыми паттернами Koan هو إطار حديث ومتوافق ل .NET 10 يسهل إنشاء تطبيقات متقدمة مع أنماط بسيطة Koan is a modern, modular .NET 10 framework designed to make small teams capable of building sophisticated applications with simple patterns. Entity-first persistence, multi-provider transparency, AI integration, event-driven architecture with zero configuration ceremony. Koan性能优化 AI智能开发框架 如何使用Koan Koan安装 Koan设置指南 Koan替代品 Koan vs Entity Framework Koan is a modern, modular .NET 10 framework designed to make small teams capable of building sophisticated applications with simple patterns. Entity-first persistence, multi-provider transparency, AI integration, event-driven architecture with zero configuration ceremony.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Falkicon/Mechanic/s-research', 'community', 'Falkicon', 'Mechanic', 'Falkicon/Mechanic', 's-research', 0, 0, 36, '2026-03-04T13:07:01.694Z', '2026-03-04T13:35:24.473Z', 'e645d572ffe340be54b39e662ef712ea196bbd8fe8033a68e49a0a6f010932c9', '{"id":"Falkicon/Mechanic/s-research","name":"s-research","description":{"zh":"s-research是魔兽世界插件开发者的游戏开发中心，提供调试、测试、错误捕获和性能监控等功能","ja":"s-researchはWorld of Warcraftアドオン開発者のためのゲーム開発ハブで、デバッグ、テスト、エラーキャプチャ、パフォーマンスモニタリングなどの機能を提供","ko":"s-research는 월드 오브 워크래프트 애드온 개발자를 위한 게임 개발 센터로, 디버깅, 테스트, 오류 캡처, 성능 모니터링 등의 기능을 제공","es":"s-research es un hub de desarrollo de addons de World of Warcraft con funciones de depuración y monitoreo de rendimiento","fr":"s-research est un hub de développement d''addons World of Warcraft avec des fonctionnalités de débogage et de surveillance des performances","de":"s-research ist ein Entwicklungs-Hub für WoW-Addons mit Debugging- und Leistungsüberwachungsfunktionen","pt":"s-research é um hub de desenvolvimento de jogos para criadores de addons de World of Warcraft, oferecendo depuração, teste, captura de erros e monitoramento de desempenho com suporte de cópia universal","ru":"s-research — это центр разработки игр для создателей аддонов World of Warcraft, предлагающий отладку, тестирование, захват ошибок и мониторинг производительности с универсальной поддержкой копирования","ar":"s-research هو مركز تطوير ألعاب لمطوري الإضافات في World of Warcraft، يقدم تصحيح الأخطاء واختبار وتصحيح الأخطاء ومراقبة الأداء مع دعم نسخة عالمية","en":"In-game development hub for World of Warcraft addon developers. Centralizes debugging, testing, error capture, and performance monitoring with universal copy support."},"seo":{"title":{"zh":"AI工具s-research：魔兽世界插件开发调试中心","ja":"AIエージェントs-research：World of Warcraftアドオン開発ハブ","ko":"AI 에이전트 s-research: 월드 오브 워크래프트 애드온 개발 센터","es":"H