INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thefixer3x/onasis-gateway/compliance-manager', 'compliance-manager', 'thefixer3x', 'onasis-gateway', 'community', 'compliance-manager thefixer3x onasis-gateway community Onasis Gateway是一种全面API服务仓库，提供MCP服务器接口和REST端点，用于智能代理管理 Onasis Gatewayは総合APIサービス倉庫で、MCPサーバーインターフェースとRESTエンドポイントを提供し、AIエージェント管理に使用 Onasis Gateway는 종합 API 서비스 저장소로, MCP 서버 인터페이스와 REST 엔드포인트를 제공하여 AI 에이전트 관리에 사용 Onasis Gateway es un servicio API integral que ofrece interfaces de servidor MCP y puntos de conexión REST para una administración de la conformidad eficaz Onasis Gateway est un service API complet qui propose des interfaces de serveur MCP et des points de terminaison REST pour une gestion efficace de la conformité Onasis Gateway ist ein umfassender API-Service, der MCP-Server-Schnittstellen und REST-Endpunkte für eine effiziente Konformitätsverwaltung bietet O Onasis Gateway é uma plataforma de serviço de API abrangente com interfaces de servidor MCP e endpoints REST para gerenciamento de conformidade Onasis Gateway - это комплексная платформа службы API с интерфейсами сервера MCP и точками REST для управления соответствием Onasis Gateway هو منصة خدمة API شاملة مع واجهات خادم MCP ونقاط نهاية REST لإدارة الامتثال Onasis Gateway - Comprehensive API service warehouse with MCP server interfaces and REST endpoints 如何使用Onasis Gateway 什么是AI智能代理 Onasis Gateway替代品 Onasis Gateway安装 Onasis Gateway设置指南 API服务仓库 MCP服务器接口 REST端点 Onasis Gateway - Comprehensive API service warehouse with MCP server interfaces and REST endpoints');
