INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cluesmith/codev/codev', 'codev', 'cluesmith', 'codev', 'community', 'codev cluesmith codev community Codev帮助人类和AI代理共同开发项目的代码和上下文，提高开发效率和质量 Codevは、人間とAIエージェントが共同でプロジェクトのコードとコンテキストを開発することを支援します Codev는 인간과 에이전트가 공동으로 프로젝트의 코드와 컨텍스트를 개발하는 것을 지원합니다 Codev es una herramienta de AI que facilita la colaboración entre humanos y agentes para desarrollar proyectos de código Codev est un outil d''IA qui facilite la collaboration entre les humains et les agents pour développer des projets de code Codev ist ein KI-Tool, das die Zusammenarbeit zwischen Menschen und Agenten bei der Entwicklung von Code-Projekten erleichtert Codev é uma ferramenta de IA que facilita a colaboração entre humanos e agentes para desenvolver projetos Codev - это ИИ инструмент, который облегчает сотрудничество между людьми и ИИ Агентами при разработке проектов كوديف هو أداة ذكاء اصطناعي تسهل التعاون بين البشر والوكلاء لتنمية المشاريع Codev helps humans and agents co-develop both the context and the code of the project. Codev AI工具 AI代理 协同开发 代码自动完成 项目上下文 如何使用Codev Codev替代品 Codev安装 Codev设置指南 Codev helps humans and agents co-develop both the context and the code of the project. ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('u9401066/pubmed-search-mcp/tool-sync', 'community', 'u9401066', 'pubmed-search-mcp', 'u9401066/pubmed-search-mcp', 'tool-sync', 0, 0, 36, '2026-03-04T13:07:01.722Z', '2026-03-04T13:52:35.286Z', '59f9bea00aa1f12ec2b9eecd8cb84c37db5e8700f0995b72b256df92447273e4', '{"id":"u9401066/pubmed-search-mcp/tool-sync","name":"tool-sync","description":{"zh":"tool-sync是一个专业的MCP服务器，用于生物医学文献研究，提供40种工具、多源搜索、全文访问、引用网络等功能","ja":"tool-syncは、バイオメディカル文献研究用のプロフェッショナルMCPサーバーであり、40のツール、多元検索、全文アクセス、引用ネットワークなどの機能を提供","ko":"tool-sync는 생물의학 문헌 연구를 위한 전문 MCP 서버로, 40가지 도구, 멀티 소스 검색, 전문 검색, 인용 네트워크 등을 제공","es":"Tool-sync es un servidor MCP profesional para investigación biomédica que ofrece acceso a 40 herramientas y texto completo","fr":"Tool-sync est un serveur MCP professionnel pour la recherche biomédicale qui offre l''accès à 40 outils et au texte complet","de":"Tool-sync ist ein professioneller MCP-Server für biomedizinische Forschung, der Zugang zu 40 Tools und Volltext bietet","pt":"O tool-sync é uma plataforma de pesquisa biomédica profissional com 40 ferramentas e acesso a texto completo","ru":"ИИ Агент tool-sync - профессиональная платформа для биомедицинских исследований с 40 инструментами","ar":"أداة tool-sync هي منصة بحث بيولوجي محترف مع 40 أداة ووصول كامل إلى النص","en":"🔬 Professional MCP server for biomedical literature research — 40 tools, multi-source search (PubMed, Europe PMC, CORE, OpenAlex), full-text access, citation networks, PICO analysis, and more"},"seo":{"title":{"zh":"AI工具 - tool-sync：专业的MCP服务器","ja":"AIエージェント - tool-sync：バイオメディカル文献研究のためのプロフェッショナルMCPサーバー","ko":"AI 에이전트 - tool-sync: 생물의학 문헌 연구를 위한 전문 MCP 서버","es":"Herramientas de investigación biomédica con tool-sync","fr":"Outil de recherche biomédicale avec tool-sync","de":"Biomedizinische Forschung mit tool-sync","pt":"Ferramentas de Pesquisa Biomédica - tool-sync","ru":"ИИ Агенты для Биомедицинских Исследований - tool-sync","ar":"أدوات البحث البيولوجي - tool-sync","en":"tool-sync"},"description":{"zh":"tool-sync是一个专业的MCP服务器，用于生物医学文献研究，提供40种工具、多源搜索、全文访问、引用网络等功能","ja":"tool-syncは、バイオメディカル文献研究用のプロフェッショナルMCPサーバーであり、40のツール、多元検索、全文アクセス、引用ネットワークなどの機能を提供","ko":"tool-sync는 생물의학 문헌 연구를 위한 전문 MCP 서버로, 40가지 도구, 멀티 소스 검색, 전문 검색, 인용 네트워크 등을 제공","es":"Tool-sync es un servidor MCP profesional para investigación biomédica que ofrece acceso a 40 herramientas y texto completo","fr":"Tool-sync est un serveur MCP professionnel pour la recherche biomédicale qui offre l''accès à 40 outils et au texte complet","de":"Tool-sync ist ein professioneller MCP-Server für biomedizinische Forschung, der Zugang zu 40 Tools und Volltext bietet","pt":"O tool-sync é uma plataforma de pesquisa biomédica profissional com 40 ferramentas e acesso a texto completo","ru":"ИИ Агент tool-sync - профессиональная платформа для биомедицинских исследований с 40 инструментами","ar":"أداة tool-sync هي منصة بحث بيولوجي محترف مع 40 أداة ووصول كامل إلى النص","en":"🔬 Professional MCP server for biomedical literature research — 40 tools, multi-source search (PubMed, Europe PMC, CORE, OpenAlex), full-text access, citatio..."},"definition":{"en":"🔬 Professional MCP server for biomedical literature research — 40 tools, multi-source search (PubMed, Europe PMC, CORE, OpenAlex), full-text access, citation networks, PICO analysis, and more"},"features":{"zh":["支持40种工具","多源搜索（PubMed、Europe PMC、CORE、OpenAlex）","全文访问","引用网络","PICO分析"],"ja":["40のツールをサポート","多元検索（PubMed、Europe PMC、CORE、OpenAlex）","全文アクセス","引用ネットワーク","PICO分析"],"ko":["40가지 도구 지원","멀티 소스 검색（PubMed、Europe PMC、CORE、OpenAlex）","전문 검색","인용 네트워크","PICO 분석"],"es":["Búsqueda multi-fuente en PubMed, Europe PMC, CORE y OpenAlex","Acceso a texto completo","Análisis de redes de citas","Análisis PICO","40 herramientas integradas"],"fr":["Recherche multi-source sur PubMed, Europe PMC, CORE et OpenAlex","Accès au texte complet","Analyse de réseaux de citations","Analyse PICO","40 outils intégrés"],"de":["Mehrquellen-Suche in PubMed, Europe PMC, CORE und OpenAlex","Volltextzugang","Zitationsnetzwerkanalyse","PICO-Analyse","40 integrierte Tools"],"pt":["40 ferramentas de pesquisa","Acesso a texto completo","Redes de citação","Análise PICO","Pesquisa multi-fonte"],"ru":["40 инструментов для поиска","Полный доступ к текстам","Сети цитирования","Анализ PICO","Многоисточниковый поиск"],"ar":["40 أداة للبحث","وصول كامل إلى النص","شبكات الاقتباس","تحليل PICO","البحث من عدة مصادر"]},"keywords":{"zh":["how to use tool-sync","什么是MCP服务器","tool-sync安装","tool-sync设置指南","tool-sync替代","tool-sync vs 其他工具","生物医学文献研究工具","MCP服务器设置"],"ja":["how to use tool-sync","MCPサーバーとは","tool-syncインストール","tool-sync設定ガイド","tool-syncの代替","tool-sync vs 他のツール","バイオメディカル文献研究ツール","MCPサーバーの設定"],"ko":["how to use tool-sync","MCP 서버란","tool-sync 설치","tool-sync 설정 가이드","tool-sync 대체","tool-sync vs 다른 도구","생물의학 문헌 연구 도구","MCP 서버 설정"],"es":["cómo usar tool-sync","qué es tool-sync","herramientas de investigación biomédica","alternativas a tool-sync","tool-sync vs otras herramientas","instalación de tool-sync","guía de configuración de tool-sync"],"fr":["comment utiliser tool-sync","qu''est-ce que tool-sync","outils de recherche biomédicale","alternatives à tool-sync","tool-sync vs autres outils","installation de tool-sync","guide de configuration de tool-sync"],"de":["wie man tool-sync verwendet","was ist tool-sync","biomedizinische Forschungstools","alternativen zu tool-sync","tool-sync im vergleich zu anderen tools","installation von tool-sync","einrichtungsanleitung für tool-sync"],"pt":["como usar tool-sync","o que é tool-sync","alternativas para tool-sync","tool-sync vs outras ferramentas","instalar tool-sync","guia de configuração do tool-sync"],"ru":["как использовать tool-sync","что такое tool-sync","альтернативы для tool-sync","tool-sync vs другие инструменты","установить tool-sync","руководство по настройке tool-sync"],"ar":["كيفية استخدام أداة tool-sync","ما هي أداة tool-sync","بديلاً لأداة tool-sync","أداة tool-sync مقابل أدوات أخرى","تثبيت أداة tool-sync","دليل إعداد أداة tool-sync"]}},"owner":"u9401066","repo":"pubmed-search-mcp","repoPath":"u9401066/pubmed-search-mcp","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.722Z","topics":[],"category":"community","skillMd":{"name":"tool-sync","description":"Auto-sync MCP tool documentation when tools are added, removed, or renamed. Triggers: TS, tool-sync, 工具同步, 同步工具, sync tools, new tool, 新增工具, 工具變更, update tools.","bodyPreview":"# MCP 工具文檔自動同步\n\n## 描述\n當 MCP 工具被新增、移除、重新命名時，自動同步所有相關文檔。\n確保 instructions、skills、README 中的工具數量和列表永遠與程式碼一致。\n\n## 觸發條件\n以下情境**必須**觸發此 Skill：\n1. 新增了 `register_*_tools()` 函數或 `@mcp.tool()` 裝飾器\n2. 修改了 `tool_registry.py` 的 `TOOL_CATEGORIES`\n3. 修改了 `tools/__init__.py` 的 `register_all_tools()`\n4. 刪除或重新命名任何 MCP 工具\n5. 用戶明確要求 \"同步工具\" / \"tool sync\"\n\n## 自動同步的文件（共 6 個）\n\n| # | 文件 | 更新內容 | 更新方式 |\n|---|------|----------|----------|\n| 1 | `presentation/mcp_server/tool_registry.py` | `TOOL_CATEGORIES` dict | 手動 — 新增/移除工","body":"# MCP 工具文檔自動同步\n\n## 描述\n當 MCP 工具被新增、移除、重新命名時，自動同步所有相關文檔。\n確保 instructions、skills、README 中的工具數量和列表永遠與程式碼一致。\n\n## 觸發條件\n以下情境**必須**觸發此 Skill：\n1. 新增了 `register_*_tools()` 函數或 `@mcp.tool()` 裝飾器\n2. 修改了 `tool_registry.py` 的 `TOOL_CATEGORIES`\n3. 修改了 `tools/__init__.py` 的 `register_all_tools()`\n4. 刪除或重新命名任何 MCP 工具\n5. 用戶明確要求 \"同步工具\" / \"tool sync\"\n\n## 自動同步的文件（共 6 個）\n\n| # | 文件 | 更新內容 | 更新方式 |\n|---|------|----------|----------|\n| 1 | `presentation/mcp_server/tool_registry.py` | `TOOL_CATEGORIES` dict | 手動 — 新增/移除工具分類 |\n| 2 | `presentation/mcp_server/tools/__init__.py` | `register_all_tools()` | 手動 — import + 呼叫 register 函數 |\n| 3 | `presentation/mcp_server/instructions.py` | SERVER_INSTRUCTIONS 工具列表 | 🤖 `--update-docs` 自動 |\n| 4 | `.github/copilot-instructions.md` | Tool Categories 表格 | 🤖 `--update-docs` 自動 |\n| 5 | `.claude/skills/pubmed-mcp-tools-reference/SKILL.md` | 完整工具參考 | 🤖 `--update-docs` 自動 |\n| 6 | `README.md` + `README.zh-TW.md` | 工具數量 badge | 🤖 `--update-docs` 自動 |\n\n## 執行流程\n\n### Step 1: 手動修改（AI Agent 負責）\n確保以下兩個「源頭」檔案正確：\n\n```python\n# 1. tool_registry.py — 新增分類\nTOOL_CATEGORIES = {\n    ...\n    \"new_category\": {\n        \"name\": \"新分類名稱\",\n        \"description\": \"分類描述\",\n        \"tools\": [\"tool_name_1\", \"tool_name_2\"],\n    },\n}\n\n# 2. tools/__init__.py — 註冊函數\nfrom .new_module import register_new_tools\n\ndef register_all_tools(mcp, searcher):\n    ...\n    register_new_tools(mcp)  # 新增呼叫\n```\n\n### Step 2: 執行自動同步腳本\n```bash\nuv run python scripts/count_mcp_tools.py --update-docs\n```\n\n### Step 3: 驗證\n```bash\n# 檢查工具數量是否正確\nuv run python scripts/count_mcp_tools.py\n\n# 檢查驗證是否通過（TOOL_CATEGORIES 與 FastMCP runtime 同步）\nuv run python scripts/count_mcp_tools.py --verbose\n```\n\n### Step 4: 回報結果\n```\n🔄 MCP 工具同步完成\n\n📊 統計：\n  - 工具總數: XX → YY (+N)\n  - 分類數: XX → YY (+N)\n  - 更新文件: N 個\n\n📝 已更新：\n  ✅ tool_registry.py - 新增 \"image_search\" 分類\n  ✅ tools/__init__.py - 新增 register_image_search_tools\n  ✅ instructions.py - 工具列表已同步\n  ✅ copilot-instructions.md - Tool Categories 已同步\n  ✅ SKILL.md (tools-reference) - 已重新生成\n  ✅ README.md - 工具數量已更新\n  ✅ README.zh-TW.md - 工具數量已更新\n\n⚠️ 驗證: PASSED ✅\n```\n\n## 重要規則\n\n### 🔴 必須遵守\n1. **任何工具變更後都要執行** `count_mcp_tools.py --update-docs`\n2. **先修改源頭**（tool_registry.py + tools/__init__.py），再執行腳本\n3. **驗證必須通過** — `TOOL_CATEGORIES` 與 FastMCP runtime 必須同步\n\n### ⚠️ 注意事項\n- `count_mcp_tools.py` 會自動偵測 `TOOL_CATEGORIES` 中所有類別（動態取得，不再硬編碼）\n- `instructions.py` 只更新工具列表區塊，搜尋策略等手寫內容不會被覆蓋\n- `pubmed-mcp-tools-reference` SKILL 會完全重新生成\n- CHANGELOG 更新由 `changelog-updater` skill 另行處理\n\n## 與其他 Skill 的關係\n- **git-precommit**: commit 前會呼叫本 Skill 的同步步驟\n- **git-doc-updater**: 文檔更新時也會觸發工具同步檢查\n- **ddd-architect**: 新增功能模組時會提醒執行工具同步\n"},"lastSynced":"2026-03-04T13:52:35.286Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated tool synchronization and documentation updates.","zh":"适合需要自动化工具同步和文档更新的开发代理。","ja":"開発エージェントが自動化ツールの同期とドキュメントの更新を必要とする場合に最適です。","ko":"자동화된 도구 동기화 및 문서 업데이트가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan la sincronización automática de herramientas y actualizaciones de documentación.","fr":"Parfait pour les agents de développement ayant besoin d''une synchronisation d''outils automatisée et de mises à jour de documentation.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Werkzeugsynchronisierung und Dokumentenaktualisierungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de sincronização de ferramentas automatizada e atualizações de documentação.","ru":"Идеально подходит для агентов разработки, которым необходима автоматизированная синхронизация инструментов и обновление документации.","ar":"مثالي لعمليات التطوير التي تحتاج إلى تزامن أدوات آلي وتحديثات توثيقية."},"recommendation":{"en":"Empowers agents to automatically synchronize tool documentation and code, ensuring consistency and accuracy. It supports multi-source search and full-text access, and can update files like `tool_registry.py` and `README.md`.","zh":"赋予代理自动同步工具文档和代码的能力，确保一致性和准确性。它支持多源搜索和全文访问，并可以更新诸如 `tool_registry.py` 和 `README.md` 之类的文件。","ja":"エージェントに自動的にツールのドキュメントとコードを同期する能力を与え、一貫性と正確性を確保します。マルチソース検索とフルテキストアクセスをサポートし、`tool_registry.py` や `README.md` などのファイルを更新できます。","ko":"에이전트가 자동으로 툴 문서와 코드를 동기화하여 일관성과 정확성을 보장하는 능력을 부여합니다. 다중 소스 검색 및 전자 접근을 지원하며, `tool_registry.py` 및 `README.md`와 같은 파일을 업데이트할 수 있습니다.","es":"Habilita a los agentes a sincronizar automáticamente la documentación de herramientas y el código, garantizando la consistencia y la precisión. Admite la búsqueda multi-origen y el acceso de texto completo, y puede actualizar archivos como `tool_registry.py` y `README.md`.","fr":"Permet aux agents de synchroniser automatiquement la documentation des outils et le code, assurant ainsi la cohérence et l''exactitude. Il prend en charge la recherche multi-source et l''accès au texte complet, et peut mettre à jour des fichiers tels que `tool_registry.py` et `README.md`.","de":"Ermächtigt Agenten, die Werkzeugdokumentation und den Code automatisch zu synchronisieren, um Konsistenz und Genauigkeit sicherzustellen. Es unterstützt die Suche in mehreren Quellen und den Volltextzugriff und kann Dateien wie `tool_registry.py` und `README.md` aktualisieren.","pt":"Concede poder aos agentes para sincronizar automaticamente a documentação de ferramentas e código, garantindo consistência e precisão. Ele suporta busca multi-fonte e acesso de texto completo, e pode atualizar arquivos como `tool_registry.py` e `README.md`.","ru":"Наделяет агентов возможностью автоматически синхронизировать документацию инструментов и код, обеспечивая согласованность и точность. Он поддерживает поиск из нескольких источников и доступ ко всему тексту, и может обновлять файлы типа `tool_registry.py` и `README.md`.","ar":"يمنح الوكلاء القدرة على مزامنة توثيق الأدوات والرمز تلقائيًا، مما يضمن الاتساق والدقة. يدعم البحث من عدة مصادر والدخول إلى النص الكامل، ويمكن تحديث الملفات مثل `tool_registry.py` و `README.md`."},"useCases":{"en":["Automating tool documentation updates","Generating consistent tool lists and categories","Debugging tool synchronization issues"],"zh":["自动化工具文档更新","生成一致的工具列表和类别","调试工具同步问题"],"ja":["自動的にツールのドキュメントを更新する","一貫したツールのリストとカテゴリを生成する","ツールの同期問題をデバッグする"],"ko":["자동으로 툴 문서를 업데이트하는 것","일관된 툴 목록 및 카테고리를 생성하는 것","툴 동기화 문제를 디버깅하는 것"],"es":["Automatización de actualizaciones de documentación de herramientas","Generación de listas y categorías de herramientas coherentes","Depuración de problemas de sincronización de herramientas"],"fr":["Automatisation des mises à jour de la documentation des outils","Génération de listes et de catégories d''outils cohérentes","Débogage des problèmes de synchronisation des outils"],"de":["Automatisierung von Werkzeugdokumenten-Aktualisierungen","Erzeugung konsistenter Werkzeuglisten und -kategorien","Fehlerbehebung bei der Werkzeugsynchronisierung"],"pt":["Automatizar atualizações de documentação de ferramentas","Gerar listas e categorias de ferramentas consistentes","Depurar problemas de sincronização de ferramentas"],"ru":["Автоматизировать обновления документации инструментов","Генерировать последовательные списки и категории инструментов","Отлаживать проблемы синхронизации инструментов"],"ar":["تأتمة تحديثات توثيق الأدوات","توليد قوائم وفئات أدوات متسقة","تصحيح مشاكل تزامن الأدوات"]},"limitations":{"en":["Requires Python 3.x+ and MCP server setup","Limited to MCP tools and documentation"],"zh":["需要 Python 3.x+ 和 MCP 服务器设置","仅限于 MCP 工具和文档"],"ja":["Python 3.x+ と MCP サーバーの設定が必要","MCP ツールとドキュメントに限定される"],"ko":["Python 3.x+ 및 MCP 서버 설정이 필요함","MCP 툴 및 문서에만 제한됨"],"es":["Requiere Python 3.x+ y configuración del servidor MCP","Limitado a herramientas y documentación de MCP"],"fr":["Nécessite Python 3.x+ et une configuration du serveur MCP","Limité aux outils et à la documentation MCP"],"de":["Benötigt Python 3.x+ und MCP-Server-Einrichtung","Begrenzt auf MCP-Tools und -Dokumentation"],"pt":["Requer Python 3.x+ e configuração do servidor MCP","Limitado às ferramentas e documentação do MCP"],"ru":["Требует Python 3.x+ и настройку сервера MCP","Ограничен инструментами и документацией MCP"],"ar":["يتطلب Python 3.x+ وإعداد خادم MCP","محدود بالأدوات وتوثيق MCP"]},"version":3},"contentHash":"59f9bea00aa1f12ec2b9eecd8cb84c37db5e8700f0995b72b256df92447273e4","qualityScore":36}');
