INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dartsim/dart/dart-ci', 'dart-ci', 'dartsim', 'dart', 'community', 'dart-ci dartsim dart community Dart-CI是一个用于机器人和动画的C++20物理引擎，具有碰撞、约束和Python绑定。它提供高性能的物理模拟和动画功能 Dart-CIはロボティクスとアニメーション向けのC++20物理エンジンで、衝突、制約、Pythonバインディングを備えています。高性能な物理シミュレーションとアニメーション機能を提供します Dart-CI는 로봇과 애니메이션을 위한 C++20 물리 엔진으로 충돌, 제약 및 Python 바인딩이 포함되어 있습니다. 고성능 물리 시뮬레이션과 애니메이션 기능을 제공합니다 dart-ci es un motor de física C++20 para robótica y animación con características de colisión y restricción, y bindings de Python para una integración fácil dart-ci est un moteur de physique C++20 pour la robotique et l''animation avec des fonctionnalités de collision et de contrainte, et des liens Python pour une intégration facile dart-ci ist ein C++20-Physik-Motor für Robotik und Animation mit Kollisions- und Einschränkungsmerkmalen sowie Python-Bindings für eine einfache Integration O dart-ci é um motor de física C++20 para robótica e animação com recursos de colisão e restrições, e bindings Python Dart-ci - это движок физики C++20 для робототехники и анимации с функциями столкновения и ограничений, и Python-биндингами dart-ci هو محرك فيزياء سي++20 للروبوتات والرسم المتحرك مع ميزات التصادم والقيود، وربط بايثون C++20 physics engine for robotics and animation with collision, constraints, and Python bindings Dart-CI C++20物理引擎 机器人和动画 如何使用Dart-CI Dart-CI教程 C++20物理引擎比较 Dart-CI安装 Dart-CI设置指南 C++20 physics engine for robotics and animation with collision, constraints, and Python bindings');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('antorsae/dual-agent/read-task', 'community', 'antorsae', 'dual-agent', 'antorsae/dual-agent', 'read-task', 0, 0, 36, '2026-03-04T13:07:01.738Z', '2026-03-04T14:04:05.698Z', '39870b52a0274aa5fcfa50556601804041b2051906f0b6f3badf1d19cebd207b', '{"id":"antorsae/dual-agent/read-task","name":"read-task","description":{"zh":"read-task双代理开发环境将Claude Code和Codex CLI整合在一起，实现高效的开发协作","ja":"read-taskの双代理開発環境は、Claude CodeとCodex CLIを組み合わせて開発効率を向上させる","ko":"read-task 쌍방향 개발 환경은 Claude Code와 Codex CLI를 결합하여 개발 효율성을 높입니다","es":"El entorno de desarrollo de agentes duales combina Claude Code con Codex CLI en una sesión colaborativa de tmux para mejorar la eficiencia del desarrollo","fr":"L''environnement de développement d''agents doubles combine Claude Code avec Codex CLI dans une session collaborative tmux pour améliorer l''efficacité du développement","de":"Die duale Agenten-Entwicklungsumgebung kombiniert Claude Code mit Codex CLI in einer kooperativen tmux-Sitzung, um die EntwicklungsEffizienz zu verbessern","pt":"O read-task é uma ferramenta de desenvolvimento que combina Claude Code e Codex CLI em uma sessão colaborativa do tmux","ru":"read-task - это инструмент разработки, сочетающий Claude Code и Codex CLI в совместной сессии tmux","ar":"read-task هو أداة تطوير تجمع بين Claude Code و Codex CLI في جلسة تعاونية من tmux","en":"Dual-agent development environment pairing Claude Code with Codex CLI in a collaborative tmux session"},"seo":{"title":{"zh":"AI智能工具：read-task双代理开发环境","ja":"AIエージェント：read-taskの双代理開発環境","ko":"AI 에이전트: read-task 쌍방향 개발 환경","es":"Entorno de desarrollo de agentes duales con Claude Code y...","fr":"Environnement de développement d''agents doubles avec Clau...","de":"Duales Agenten-Entwicklungsumgebung mit Claude Code und C...","pt":"Ferramentas de AI: read-task com Claude Code e Codex CLI","ru":"ИИ Аге