INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('filipstrand/mflux/mflux-pr', 'mflux-pr', 'filipstrand', 'mflux', 'community', 'mflux-pr filipstrand mflux community mflux-pr是一个基于MLX的AIエージェント，提供最新的生成性图片模型实现 mflux-prは、MLXで実装されたAIエージェントで、最新の画像生成モデルを実現します mflux-pr는 MLX 기반의 AI 에이전트로, 최첨단 이미지 생성 모델을 구현합니다 mflux-pr ofrece implementaciones nativas de MLX para modelos de imágenes generativas de última generación, mejorando la eficiencia y la calidad de tus proyectos de desarrollo mflux-pr propose des implémentations natives MLX pour les modèles d''images génératives de pointe, améliorant l''efficacité et la qualité de vos projets de développement mflux-pr bietet native MLX-Implementierungen für generative Bildmodelle der neuesten Generation, um die Effizienz und Qualität Ihrer Entwicklungsprojekte zu verbessern O mflux-pr é uma ferramenta de inteligência artificial que permite a criação de imagens gerativas com modelos de inteligência artificial mflux-pr - это инструмент ИИ, который позволяет создать генеративные изображения с помощью моделей ИИ mflux-pr هو أداة الذكاء الاصطناعي التي تسمح بإنشاء صور تلقية باستخدام نماذج الذكاء الاصطناعي MLX native implementations of state-of-the-art generative image models 如何使用mflux-pr 什么是AIエージェント mflux-pr替代品 mflux-pr vs 其他AI工具 mflux-pr安装 mflux-pr设置指南 MLX图片生成 生成性图片模型 MLX native implementations of state-of-the-art generative image models');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kweaver-ai/adp/bkn-modeling', 'community', 'kweaver-ai', 'adp', 'kweaver-ai/adp', 'bkn-modeling', 0, 0, 36, '2026-03-04T13:07:01.796Z', '2026-03-04T14:28:28.557Z', 'eb97fa02f01f4f9b28df205f9ef86556d34bb7f908cbd43e1f0907cd9e14f35e', '{"id":"kweaver-ai/adp/bkn-modeling","name":"bkn-modeling","description":{"zh":"BKN建模是ADP智能数据平台的一部分，通过业务知识网络抽象数据复杂性，提供统一数据访问和DataFlow管道","ja":"BKNモデリングは、ADPのインテリジェントデータプラットフォームの一部であり、ビジネスノウレッジネットワークを通じてデータの複雑性を抽象化し、統一データアクセスとDataFlowパイプラインを提供する","ko":"BKN 모델링은 ADP의 지능형 데이터 플랫폼의 일부로서 비즈니스 지식 네트워크를 통해 데이터의 복잡성을 추상화하고,統一 데이터 액세스 및 DataFlow 파이프라인을 제공","es":"ADP es una plataforma de datos inteligente que conecta fuentes de datos heterogéneas con agentes de inteligencia artificial a través de redes de conocimiento empresarial","fr":"ADP est une plateforme de données intelligente qui relie les sources de données hétérogènes aux agents d''intelligence artificielle via des réseaux de connaissances métier","de":"ADP ist eine intelligente Datenplattform, die heterogene Datenquellen mit KI-Agents über Geschäftswissen-Netzwerke verbindet","pt":"A plataforma ADP é uma solução inteligente que une fontes de dados heterogêneas e ferramentas de IA com modelagem bkn","ru":"Платформа ADP - это интеллектуальное решение, которое объединяет разнообразные источники данных и ИИ Агенты с помощью моделирования bkn","ar":"منصة ADP هي حل ذكي يربط بين مصادر البيانات المتنوعة وأدوات الذكاء الاصطناعي مع نمذجة bkn","en":"ADP is an intelligent data platform that bridges the gap between heterogeneous data sources and AI agents. It abstracts data complexity through business knowledge networks (Ontology), provides unified data access (VEGA), and orchestrates data processing through DataFlow pipelines."},"seo":{"title":{"zh":"BKN建模 - 智能数据平台ADP中的AIエージェント","ja":"BKNモデリング - インテリジェントデータプラットフォームADPのAIエージェント","ko":"BKN 모델