INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GELLIFY/acme-app/better-auth-security-best-practices', 'better-auth-security-best-practices', 'GELLIFY', 'acme-app', 'community', 'better-auth-security-best-practices GELLIFY acme-app community Better Auth Security最佳实践为您的全栈应用提供专业的安全方案，提高安全性和防护能力 Better Auth Securityのベストプラクティスは、全栈アプリのセキュリティを高めるための専門的なセキュリティソリューションを提供する Better Auth Security 최적화 가이드는 전체 스택 애플리케이션의 보안을 강화하고 전문 보안 솔루션을 제공한다 Esta plantilla de mejores prácticas para Agentes de IA y aplicaciones full-stack de GELLIFY está configurada para usar las mejores integraciones para nuestros proyectos estándar Ce modèle de meilleures pratiques pour les Outils d''IA et les applications full-stack de GELLIFY est configuré pour utiliser les meilleures intégrations pour nos projets standard Diese Vorlage für die besten Praktiken von KI-Agents und Full-Stack-Anwendungen von GELLIFY ist konfiguriert, um die besten Integrationen für unsere Standardprojekte zu verwenden O agente AI de melhor autenticação fornece um modelo de aplicativo full-stack configurado para usar as melhores integrações para projetos padrão ИИ Агент для лучшей аутентификации предоставляет шаблон для полнофункционального приложения, настроенного для использования лучших интеграций для стандартных проектов أداة المصادقة المُحسنة توفر قوالب تطبيقات كاملة متوافقة مع أفضل التكاملات للمشاريع المعيارية This is template for GELLIFY full-stack app configured to use the best integrations for our standard projects. AI智能代理 Better Auth Security 全栈应用安全 身份验证和授权 安全方案 如何提高全栈应用安全性 全栈应用安全最佳实践 AI智能代理安装 Better Auth Security设置指南 This is template for GELLIFY full-stack app configured to use the best integrations for our standard projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AlbertoBasalo/astro-bookings-express/planning-specs', 'community', 'AlbertoBasalo', 'astro-bookings-express', 'AlbertoBasalo/astro-bookings-express', 'planning-specs', 0, 0, 36, '2026-03-04T13:07:01.810Z', '2026-03-04T14:33:19.742Z', 'f5a079d705f2751bd45b12d52593cedd8833a82ad000861afbcc84348871ab89', '{"id":"AlbertoBasalo/astro-bookings-express/planning-specs","name":"planning-specs","description":{"zh":"AI智能代理规划规格是Astro Bookings Express版的技术解决方案，帮助开发者提高效率","ja":"AIエージェントの計画スペックはAstro Bookings Express版の技術解決策であり、開発者の効率を向上させる","ko":"AI 에이전트 계획 사양은 Astro Bookings Express 버전의 기술 솔루션으로 개발자의 효율성을 높인다","es":"La planificación de especs para Astro Bookings es una herramienta de AI que utiliza Express para mejorar la eficiencia. Aprende a usarla","fr":"La planification de specs pour Astro Bookings est un outil d''IA qui utilise Express pour améliorer l''efficacité. Apprenez à l''utiliser","de":"Die Planung von Specs für Astro Bookings ist ein AI-Tool, das Express verwendet, um die Effizienz zu verbessern. Lernen Sie, es zu nutzen","pt":"O planning-specs é uma ferramenta de planejamento de especificações para Astro Bookings, permitindo uma integração perfeita com o Express","ru":"Планирование Спецификаций - это инструмент для планирования спецификаций для Astro Bookings, предназначенный для работы с Express","ar":"التخطيط للمواصفات هو أداة تخطيط للمواصفات للحجز الفضائي، تمكن من التكامل المثالي مع Express","en":"Express version for Astro Bookings"},"seo":{"title":{"zh":"AI智能代理规划规格 - Astro Bookings Express版","ja":"AIエージェントの計画スペック - Astro Bookings Express版","ko":"AI 에이전트 계획 사양 - Astro Bookings Express 버전","es":"Herramientas de planificación para Astro Bookings con Exp...","fr":"Outils de planification pour Astro Bookings avec Express","de":"Planungstools für Astro Bookings mit Express","pt":"Ferramentas de Planejamento d