INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-gemini/gemini-cli/pr-creator', 'pr-creator', 'google-gemini', 'gemini-cli', 'community', 'pr-creator google-gemini gemini-cli community pr-creator是一个开源的AI智能工具，直接将Gemini集成到您的终端，提供更高效的开发体验 pr-creatorはオープンソースのAIエージェントで、Geminiをターミナルに直接導入し、開発者に更なる効率的な開発体験を提供する pr-creator는 오픈소스의 AI 에이전트로서 Gemini를 터미널에 직접 통합하여 개발자에게 더욱 효율적인 개발 경험을 제공한다 Pr-creator es un agente AI de código abierto que trae la potencia de Gemini directamente a tu terminal, mejorando tu flujo de trabajo Pr-creator est un agent IA open-source qui apporte la puissance de Gemini directement dans votre terminal, améliorant votre flux de travail Pr-creator ist ein Open-Source-AI-Agent, der die Leistung von Gemini direkt in Ihr Terminal bringt, Ihren Arbeitsablauf verbessert O pr-creator é um agente de IA de código aberto que integra o Gemini no seu terminal, permitindo uma experiência de desenvolvimento mais eficiente ИИ Агент pr-creator - это открытый агент, который интегрирует Gemini в ваш терминал, обеспечивая более эффективный опыт разработки أداة pr-creator هي أداة ذكاء اصطناعي مفتوحة المصدر تعمل على دمج Gemini في جهازك، مما يتيح لك تجربة تطوير أكثر كفاءة An open-source AI agent that brings the power of Gemini directly into your terminal. 如何使用pr-creator 什么是AI智能工具 pr-creator替代品 pr-creator vs 其他AI工具 pr-creator安装 pr-creator设置指南 AI智能工具开发 终端集成开发 An open-source AI agent that brings the power of Gemini directly into your terminal.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bybren-llc/story-systems-template/logline', 'community', 'bybren-llc', 'story-systems-template', 'bybren-llc/story-systems-template', 'logline', 0, 0, 36, '2026-03-04T13:07:01.890Z', '2026-03-04T14:54:30.180Z', 'f5f7c6ddd66ddb52c6183af56bf90a5a44f9919f353266c2e9a6030fb710a429', '{"id":"bybren-llc/story-systems-template/logline","name":"logline","description":{"zh":"logline是一种创意项目模板，用于屏剧、小说和电影制作，具有多AI协同和上游同步功能","ja":"loglineは、スクリーン プレイ、ノベル、映画制作のためのクリエイティブ プロジェクト テンプレートで、多AIハーネスと上流同期を備えています","ko":"logline은 스크린 플레이, 소설, 영화 제작을 위한 창의적 프로젝트 템플릿으로 다중 AI 하네스 및 업스트림 동기화를 지원","es":"Logline es una plantilla de proyecto creativo para screenplays, novelas y producción de cine, impulsada por tecnología de IA","fr":"Logline est un modèle de projet créatif pour scénarios, romans et production de films, propulsé par la technologie d''IA","de":"Logline ist ein kreatives Projekt-Template für Drehbücher, Romane und Filmproduktion, angetrieben von KI-Technologie","pt":"Logline é uma ferramenta de IA para projetos criativos, incluindo screenplays, novels e produção de filmes, com sincronização upstream","ru":"Logline - это инструмент ИИ для креативных проектов, включая сценарии, романы и кинопроизводство, с синхронизацией upstream","ar":"لوجلاين هي أداة ذكاء اصطناعي للمشاريع الإبداعية، بما في ذلك كتابة السيناريو والروايات وإنتاج الأفلام، مع مزامنة 업스트림","en":"Creative project template for screenplays, novels, and film production. Multi-AI harness with upstream sync."},"seo":{"title":{"zh":"AI智能工具-logline：创意项目模板","ja":"AIエージェント-logline：クリエイティブプロジェクトテンプレート","ko":"AI 에이전트-logline: 창의적 프로젝트 템플릿","es":"Herramientas de AI: Plantilla de proyecto creativo logline","fr":"Outils d''IA: Modèle de projet créatif logline","de":"KI-Tools: Kreatives Projekt-Template logline","pt":"Ferramentas de IA: Logline para Projetos Criativos","ru":"ИИ 